window.CC.p.push({n:13,view:"<section class=\"view\" id=\"p13\" hidden style=\"--c:#6d4c41\"><h1><i>13</i>Orthopedics</h1><p class=\"lead\">32 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 13A</h3><div class=\"card\" data-u=\"u323\"><button class=\"open\" data-u=\"u323\"><b>Overview</b><span>Orthopedics — Fracture Principles, Upper Limb Trauma &amp;</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Orthopedics+%E2%80%94+Fracture+Principles%2C+Upper+Limb+Trauma+%26+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u324\"><button class=\"open\" data-u=\"u324\"><b>Case 1</b><span>General Principles of Fractures &amp; Open Fractures (GUSTILO-ANDERSON)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=General+Principles+of+Fractures+%26+Open+Fractures+%28GUSTILO-ANDERSON%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u325\"><button class=\"open\" data-u=\"u325\"><b>Case 2</b><span>Clavicle Fracture &amp; Acromioclavicular (AC) Joint Separation</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Clavicle+Fracture+%26+Acromioclavicular+%28AC%29+Joint+Separation\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u326\"><button class=\"open\" data-u=\"u326\"><b>Case 3</b><span>Anterior &amp; Posterior Shoulder Dislocation</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Anterior+%26+Posterior+Shoulder+Dislocation\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u327\"><button class=\"open\" data-u=\"u327\"><b>Case 4</b><span>Proximal Humerus &amp; Humeral Shaft Fractures</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Proximal+Humerus+%26+Humeral+Shaft+Fractures\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u328\"><button class=\"open\" data-u=\"u328\"><b>Case 5</b><span>Pediatric Supracondylar Humerus Fracture</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Supracondylar+Humerus+Fracture\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u329\"><button class=\"open\" data-u=\"u329\"><b>Case 6</b><span>Elbow Dislocation, Radial Head Fracture &amp; Nursemaidʼs Elbow</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Elbow+Dislocation%2C+Radial+Head+Fracture+%26+Nursemaid%CA%BCs+Elbow\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u330\"><button class=\"open\" data-u=\"u330\"><b>Case 7</b><span>Forearm Fractures (MONTEGGIA VS. GALEAZZI VS. BOTH-BONE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Forearm+Fractures+%28MONTEGGIA+VS.+GALEAZZI+VS.+BOTH-BONE%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u331\"><button class=\"open\" data-u=\"u331\"><b>Case 8</b><span>Distal Radius Fractures (COLLESʼ VS. SMITHʼS VS. BARTONʼS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Distal+Radius+Fractures+%28COLLES%CA%BC+VS.+SMITH%CA%BCS+VS.+BARTON%CA%BCS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u332\"><button class=\"open\" data-u=\"u332\"><b>Case 9</b><span>Scaphoid Fracture &amp; Boxerʼs Fracture</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Scaphoid+Fracture+%26+Boxer%CA%BCs+Fracture\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u333\"><button class=\"open\" data-u=\"u333\"><b>Case 10</b><span>Trigger Finger, DE Quervainʼs Tenosynovitis &amp; Mallet / Jersey Finger</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Trigger+Finger%2C+DE+Quervain%CA%BCs+Tenosynovitis+%26+Mallet+%2F+Jersey+Finger\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 13B</h3><div class=\"card\" data-u=\"u334\"><button class=\"open\" data-u=\"u334\"><b>Case 11</b><span>Pelvic Ring Fractures &amp; Acetabular Fractures</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pelvic+Ring+Fractures+%26+Acetabular+Fractures\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u335\"><button class=\"open\" data-u=\"u335\"><b>Case 12</b><span>HIP Dislocation (POSTERIOR VS. ANTERIOR)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=HIP+Dislocation+%28POSTERIOR+VS.+ANTERIOR%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u336\"><button class=\"open\" data-u=\"u336\"><b>Case 13</b><span>Femoral Neck Fracture (INTRACAPSULAR HIP FRACTURE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Femoral+Neck+Fracture+%28INTRACAPSULAR+HIP+FRACTURE%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u337\"><button class=\"open\" data-u=\"u337\"><b>Case 14</b><span>Intertrochanteric &amp; Subtrochanteric Femoral Fractures</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Intertrochanteric+%26+Subtrochanteric+Femoral+Fractures\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u338\"><button class=\"open\" data-u=\"u338\"><b>Case 15</b><span>Femoral Shaft Fracture &amp; FAT Embolism Syndrome (FES) Risk</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Femoral+Shaft+Fracture+%26+FAT+Embolism+Syndrome+%28FES%29+Risk\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u339\"><button class=\"open\" data-u=\"u339\"><b>Case 16</b><span>Knee Ligament &amp; Meniscal Injuries (ACL, PCL, MCL, LCL)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Knee+Ligament+%26+Meniscal+Injuries+%28ACL%2C+PCL%2C+MCL%2C+LCL%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u340\"><button class=\"open\" data-u=\"u340\"><b>Case 17</b><span>Tibial Plateau &amp; Tibial Shaft Fractures</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Tibial+Plateau+%26+Tibial+Shaft+Fractures\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u341\"><button class=\"open\" data-u=\"u341\"><b>Case 18</b><span>Ankle Sprains (OTTAWA ANKLE RULES) &amp; Ankle Fractures</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ankle+Sprains+%28OTTAWA+ANKLE+RULES%29+%26+Ankle+Fractures\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u342\"><button class=\"open\" data-u=\"u342\"><b>Case 19</b><span>Achilles Tendon Rupture &amp; Plantar Fasciitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Achilles+Tendon+Rupture+%26+Plantar+Fasciitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u343\"><button class=\"open\" data-u=\"u343\"><b>Case 20</b><span>Calcaneal Fracture &amp; Lisfranc Midfoot Injury</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Calcaneal+Fracture+%26+Lisfranc+Midfoot+Injury\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 13C</h3><div class=\"card\" data-u=\"u344\"><button class=\"open\" data-u=\"u344\"><b>Overview</b><span>Orthopedics — Infections, Spine, Shoulder, Tumors &amp;</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Orthopedics+%E2%80%94+Infections%2C+Spine%2C+Shoulder%2C+Tumors+%26+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u345\"><button class=\"open\" data-u=\"u345\"><b>Case 21</b><span>Acute Septic Arthritis (ADULT &amp; PEDIATRIC)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Septic+Arthritis+%28ADULT+%26+PEDIATRIC%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u346\"><button class=\"open\" data-u=\"u346\"><b>Case 22</b><span>Acute &amp; Chronic Osteomyelitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+%26+Chronic+Osteomyelitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u347\"><button class=\"open\" data-u=\"u347\"><b>Case 23</b><span>Spinal Trauma &amp; Incomplete Spinal Cord Syndromes</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Spinal+Trauma+%26+Incomplete+Spinal+Cord+Syndromes\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u348\"><button class=\"open\" data-u=\"u348\"><b>Case 24</b><span>Cervical Radiculopathy/myelopathy &amp; Lumbar Spinal Stenosis / Spondylolisthesis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cervical+Radiculopathy%2Fmyelopathy+%26+Lumbar+Spinal+Stenosis+%2F+Spondylolisthesis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u349\"><button class=\"open\" data-u=\"u349\"><b>Case 25</b><span>Rotator Cuff Tear, Impingement &amp; Frozen Shoulder</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Rotator+Cuff+Tear%2C+Impingement+%26+Frozen+Shoulder\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u350\"><button class=\"open\" data-u=\"u350\"><b>Case 26</b><span>Osteoporosis &amp; Fragility Fractures</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Osteoporosis+%26+Fragility+Fractures\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u351\"><button class=\"open\" data-u=\"u351\"><b>Case 27</b><span>Bone Tumors (BENIGN VS. MALIGNANT &amp; METASTATIC)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Bone+Tumors+%28BENIGN+VS.+MALIGNANT+%26+METASTATIC%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u352\"><button class=\"open\" data-u=\"u352\"><b>Case 28</b><span>Developmental Dysplasia of the HIP (DDH) &amp; Congenital Clubfoot</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Developmental+Dysplasia+of+the+HIP+%28DDH%29+%26+Congenital+Clubfoot\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u353\"><button class=\"open\" data-u=\"u353\"><b>Case 29</b><span>Pediatric HIP Limp — Transient Synovitis vs. Perthes vs. SCFE</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+HIP+Limp+%E2%80%94+Transient+Synovitis+vs.+Perthes+vs.+SCFE\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u354\"><button class=\"open\" data-u=\"u354\"><b>Case 30</b><span>FAT Embolism Syndrome (FES) &amp; Complex Regional Pain Syndrome (CRPS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=FAT+Embolism+Syndrome+%28FES%29+%26+Complex+Regional+Pain+Syndrome+%28CRPS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u323\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Overview</span><h1>Orthopedics — Fracture Principles, Upper Limb Trauma &amp;</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Orthopedics+%E2%80%94+Fracture+Principles%2C+Upper+Limb+Trauma+%26+medical\">🔍 Search on Google</a></header><h4><b>HAND DISORDERS (CASES 1–10)</b></h4><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u324\">Case 1 →</button></nav></article><article class=\"view unit\" id=\"u324\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 1</span><h1>General Principles of Fractures &amp; Open Fractures (GUSTILO-ANDERSON)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=General+Principles+of+Fractures+%26+Open+Fractures+%28GUSTILO-ANDERSON%29\">🔍 Search on Google</a></header><h3><b>1. Definitions</b></h3><ul>\n<li class=\"l1\"><b>Fracture:</b> Complete or incomplete disruption in the structural continuity of bone cortex and/or trabeculae.</li>\n<li class=\"l1\"><b>Open (Compound) Fracture:</b> A fracture in which the fracture hematoma communicates directly with the external environment through an overlying skin/soft tissue wound (<b>True Orthopedic Emergency</b> due to high risk of osteomyelitis and nonunion!).</li>\n</ul><h3><b>2. Etiology of Fractures (Separated by Mechanism)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Traumatic Fractures (Normal Bone + Excessive Force):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Direct trauma:</i> Bending, crushing, or penetrating force at impact site (e.g., transverse/comminuted fractures).</li>\n<li class=\"l2\"><i>Indirect trauma:</i> Rotational, axial, or avulsion force transmitted from a distance (e.g., spiral tibial fracture from twisting).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Stress (Fatigue) Fractures:</b> Repetitive sub-maximal cyclical loading on normal bone exceeding bone remodeling capacity (e.g., military recruits / runners — <b>\"March Fracture\"</b> of the 2nd metatarsal neck!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Pathologic Fractures (Abnormal Weakened Bone + Minimal/Trivial Trauma):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Metabolic:</i> <mark class=\"hl lab\"><b>Osteoporosis</b></mark> (#1 overall!), Osteomalacia/Rickets, Paget’s disease.</li>\n<li class=\"l2\"><i>Neoplastic:</i> <b>Bone Metastases</b> (<b>Breast, Lung, Prostate, Kidney, Thyroid</b> — <b>\"BLT with Kosher Pickle\"</b>), Multiple Myeloma, Primary bone tumors.</li>\n<li class=\"l2\"><i>Infectious / Congenital:</i> Chronic osteomyelitis, <b>Osteogenesis Imperfecta</b>.</li>\n</ul><h3><b>3. Pathophysiology of Open Fractures &amp; Bone Healing</b></h3><p>When skin integrity breaks, external flora (<i>Staphylococcus aureus</i>, Gram-negative rods, soil <i>Clostridia</i>) contaminate devitalized bone and muscle. Normal bone healing progresses through <b>4 overlapping stages:</b> (1) Hematoma formation &amp; inflammation, (2) Soft fibrocartilaginous callus, (3) Hard bony callus (endochondral/intramembranous ossification), and (4) Bone remodeling (Wolff’s Law).</p><h3><b>4. Clinical Picture &amp; Gustilo-Anderson Classification of Open Fractures</b></h3><ul>\n<li class=\"l1\"><b>General Fracture Signs:</b> Pain, swelling, bruising, focal bony tenderness, deformity, abnormal mobility, crepitus, loss of function (<b>ALWAYS document distal Neurovascular Status [pulses, capillary refill, motor, sensation] BEFORE and AFTER any reduction or splinting!</b>).</li>\n<li class=\"l1\"><b>Gustilo-Anderson Open Fracture Grades:</b></li>\n<li class=\"l2\"><b>Grade I:</b> Clean wound <b>&lt; 1 cm</b>, minimal soft-tissue damage, simple fracture pattern.</li>\n<li class=\"l2\"><b>Grade II:</b> Wound <b>1 – 10 cm</b>, moderate soft-tissue damage without extensive stripping/flaps.</li>\n<li class=\"l2\"><b>Grade III:</b> Wound <b>&gt; 10 cm</b> (OR any <b>high-energy</b> trauma, segmental fracture, <b>farmyard/soil contamination</b>, or <b>gunshot</b> regardless of wound size!):</li>\n<li class=\"l1\"><i>IIIA:</i> Adequate soft tissue remains to cover bone.</li>\n<li class=\"l1\"><i>IIIB:</i> Extensive periosteal stripping requiring <b>plastic surgical flap coverage</b>.</li>\n<li class=\"l1\"><i>IIIC:</i> <b>Any open fracture WITH an Arterial Injury requiring vascular repair</b> (highest amputation risk!).</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Standard \"Rule of Twos\" Radiographs (X-Rays):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>2 Views:</b> <b>AP</b> (Anteroposterior) and <b>Lateral</b> orthogonal views.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>2 Joints:</b> Include the <b>joint ABOVE and joint BELOW</b> the fracture (never miss Monteggia/Galeazzi/hip dislocation!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>2 Times:</b> Before and after reduction.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>2 Limbs:</b> Compare contralateral limb in children (open epiphyseal growth plates!).</span></p>\n<ul>\n<li class=\"l1\"><b>CT</b> (Computed Tomography) for complex intra-articular fractures; <mark class=\"hl mech\"><b>MRI</b></mark> (Magnetic Resonance Imaging) for occult stress/scaphoid/hip fractures.</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Ligamentous sprain/strain, Joint dislocation, Soft-tissue contusion, Pathologic tumor fracture, Non-accidental trauma (<b>Child Abuse</b> — suspect if spiral femur/humerus fracture in non-ambulatory infant, posterior rib fractures, metaphyseal corner fractures, or inconsistent history!).</li>\n</ul><h3><b>7. Complications (Separated — Early vs. Late)</b></h3><ul>\n<li class=\"l1\"><b>Early Local:</b> <b>Acute Compartment Syndrome</b>, Neurovascular injury, Soft-tissue necrosis, <b>Acute Osteomyelitis / Gas Gangrene</b>.</li>\n<li class=\"l1\"><b>Early Systemic:</b> <b>Hemorrhagic Shock</b> (pelvic/femoral fractures), <b>Fat Embolism Syndrome (FES)</b>, <mark class=\"hl lab\"><b>DVT/PE</b></mark> (Deep Vein Thrombosis / Pulmonary Embolism), <b>Rhabdomyolysis / Crush Syndrome</b>.</li>\n<li class=\"l1\"><b>Late:</b> <b>Malunion</b> (healed in deformed position), <b>Delayed Union</b>, <b>Nonunion</b> (atrophic vs. hypertrophic), <b>AVN</b> (Avascular Necrosis), Joint stiffness, <mark class=\"hl lab\"><b>Post-traumatic Osteoarthritis</b></mark> , <b>Myositis Ossificans</b>.</li>\n</ul><h3><b>8. Treatment of Open Fractures (GOLDEN 6-HOUR EMERGENCY PROTOCOL!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>ATLS</b> (Advanced Trauma Life Support) <b>ABCDEs FIRST</b> (rule out life-threatening hemorrhage/chest/head injury!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Immediate IV</b> (Intravenous) <b>Antibiotics (Single Most Important Factor Reducing Infection — Give Within 1 Hour!):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Grade I &amp; II:</i> <b>IV Cefazolin</b> (1st-generation cephalosporin covering <i>S. aureus</i>/Streptococci).</li>\n<li class=\"l2\"><i>Grade III:</i> <mark class=\"hl rx\"><b>IV Cefazolin PLUS IV Gentamicin</b></mark> (or <mark class=\"hl rx\"><b>Ceftriaxone / Piperacillin-Tazobactam</b></mark> — adds Gram-negative coverage!).</li>\n<li class=\"l2\"><i>Farmyard / Soil / Standing Water / Crush:</i> <b>ADD IV Penicillin G</b> (or Ampicillin/Metronidazole) for <i><b>Clostridium</b></i> coverage!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Tetanus Prophylaxis:</b> Give <b>Tdap/Td</b> vaccine (+/- <b>TIG</b> [Tetanus Immunoglobulin] if dirty wound and &lt; 3 lifetime doses or unknown!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Wound Care in ER:</b> Photograph wound -&gt; remove gross debris -&gt; cover with <b>sterile saline-soaked gauze</b> (do NOT probe or irrigate unsterilely in ER!) -&gt; splint limb -&gt; check distal pulses!</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Urgent OR (Operating Room) Surgical Debridement &amp; Copious Irrigation + Stabilization:</b></mark> Usually <b>External Fixation</b> for contaminated/unstable Grade III fractures (or <b>IM</b> [Intramedullary] <b>Nailing</b> / <b>ORIF</b> [Open Reduction Internal Fixation] for clean Grade I–II)!</span></p>\n<p><b>Clinical Pearl:</b> <i>A \"Simple\" Closed Fracture with persistent excruciating pain unrelieved by morphine + pain on passive toe/finger stretch = </i><mark class=\"hl lab\"><i><b>Acute Compartment Syndrome</b></i></mark><i> until proven otherwise!</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u323\">← Overview</button><button class=\"nv\" data-u=\"u325\">Case 2 →</button></nav></article><article class=\"view unit\" id=\"u325\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 2</span><h1>Clavicle Fracture &amp; Acromioclavicular (AC) Joint Separation</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Clavicle+Fracture+%26+Acromioclavicular+%28AC%29+Joint+Separation\">🔍 Search on Google</a></header><h3><b>1. Definitions</b></h3><ul>\n<li class=\"l1\"><b>Clavicle Fracture:</b> Break in the S-shaped collarbone (<b>#1 Most Common Fracture in Childhood</b> and overall ~5–10% of all fractures!).</li>\n<li class=\"l1\"><b>AC</b> (Acromioclavicular) <b>Joint Separation:</b> Tear of the AC and/or <b>CC</b> (Coracoclavicular — conoid &amp; trapezoid) ligaments connecting the distal clavicle to the acromion.</li>\n</ul><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Direct Blow to Lateral Shoulder (Most Common for Both!):</b> Sports tackle, cycling/motorcycle fall onto the point of the shoulder.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>FOOSH</b> (Fall Onto Outstretched Hand): Force transmitted up the arm to the clavicle.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Birth Trauma:</b> Shoulder dystocia during difficult vaginal delivery in macrosomic newborns.</span></p><h3><b>3. Pathophysiology &amp; Anatomical Subtypes</b></h3><ul>\n<li class=\"l1\"><b>Clavicle (~80% Middle Third):</b> <b>SCM</b> (Sternocleidomastoid) pulls the medial fragment <b>UPWARD</b>, while weight of the arm + Pectoralis major pull the lateral fragment <mark class=\"hl lab\"><b>DOWNWARD &amp; MEDIALLY</b></mark> .</li>\n<li class=\"l1\"><b>AC Joint (Rockwood Grades I–VI):</b> <i>Grade I–II:</i> AC ligament sprain/tear with intact CC ligaments -&gt; minimal displacement. <i>Grade III–VI:</i> Both AC &amp; CC ligaments torn -&gt; upward (or inferior/posterior) clavicular displacement!</li>\n</ul><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Patient cradles affected arm close to chest with the opposite hand, tilting head toward injured side (relaxes SCM!).</li>\n<li class=\"l1\"><b>Clavicle Fracture:</b> Focal swelling, ecchymosis, palpable step-off/crepitus over mid-clavicle. <b>CRITICAL CHECK:</b> Inspect overlying skin for <b>\"tenting\"</b> (white blanched skin threatening perforation!), check <b>Brachial Plexus &amp; Subclavian Vessels</b>, and auscultate lungs (<b>Pneumothorax!</b>).</li>\n<li class=\"l1\"><b>AC Separation:</b> Focal tenderness over <b>AC joint</b> with a visible/palpable <b>\"Piano-Key\" / Step-Off Deformity</b> (presses down and springs back up!), pain on cross-body adduction!</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Clavicle:</b> <b>AP and 15–30° Cephalic Tilt Clavicle X-Rays</b> (+ CXR if pneumothorax suspected).</li>\n<li class=\"l1\"><b>AC Joint:</b> Bilateral shoulder AP + <b>Zanca View</b> (10–15° cephalic tilt; axillary view rules out posterior displacement).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Anterior/Posterior Shoulder Dislocation, Proximal Humerus Fracture, Sternoclavicular Dislocation (<b>Posterior SC dislocation is an airway/great vessel emergency!</b>), Rotator Cuff Tear.</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\"><b>Clavicle:</b> Malunion (cosmetic bump — usually asymptomatic), Nonunion (~5–15% if severely displaced/shortened &gt; 2 cm), Skin necrosis/open fracture (from tenting), Brachial plexus/subclavian injury (rare).</li>\n<li class=\"l1\"><b>AC Joint:</b> Persistent cosmetic bump, late AC joint osteoarthritis.</li>\n</ul><h3><b>8. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Middle-Third Clavicle Fracture (Non-Displaced / Minimally Displaced — ~85–90%):</b></li>\n<li class=\"l2\"><b>Simple Arm Sling</b> (just as effective &amp; far more comfortable than figure-of-8 brace!) for 2–4 weeks + analgesia + early gentle pendulum exercises once pain subsides!</li>\n<li class=\"l2\"><i>Indications for Surgery (ORIF with Plate &amp; Screws):</i> <b>Open fracture</b>, <b>Skin tenting</b> (impending open fracture!), <b>Neurovascular compromise</b>, <b>\"Floating Shoulder\" </b>(clavicle + scapular neck fracture), or <b>&gt; 2 cm shortening / 100% displacement</b> in active young adults!</li>\n<li class=\"l1\"><b>AC Joint Separation:</b></li>\n<li class=\"l2\"><i>Rockwood Grades I &amp; II (and most Grade III):</i> <b>Non-operative — Arm Sling</b> × 1–3 weeks + ice + physical therapy!</li>\n<li class=\"l2\"><i>Rockwood Grades IV, V, VI (and high-demand overhead athletes with Grade III):</i> <b>Surgical Ligament Reconstruction (CC stabilization)</b>.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u324\">← Case 1</button><button class=\"nv\" data-u=\"u326\">Case 3 →</button></nav></article><article class=\"view unit\" id=\"u326\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 3</span><h1>Anterior &amp; Posterior Shoulder Dislocation</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Anterior+%26+Posterior+Shoulder+Dislocation\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Complete loss of articular contact between the <b>humeral head</b> and the <b>glenoid fossa</b> of the scapula. <b>The Glenohumeral Joint is the #1 Most Commonly Dislocated Major Joint in the Body (~50% of all dislocations)!</b></p><h3><b>2. Etiology (Separated by Direction!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Anterior Shoulder Dislocation (~95% — Most Common!):</b></span></p>\n<ul>\n<li class=\"l2\">Forced <mark class=\"hl lab\"><b>ABDUCTION + EXTERNAL ROTATION + EXTENSION</b></mark> of the arm (e.g., blocking a basketball shot, fall onto outstretched arm, tackle).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Posterior Shoulder Dislocation (~2–4% — CLASSICALLY MISSED!):</b></mark></span></p>\n<ul>\n<li class=\"l2\">Violent involuntary internal-rotator muscle contraction (<b>\"3 Es\": Epilepsy [Generalized Seizures!], Electric Shock, Ethanol/MVC trauma!</b>) or direct anterior blow forcing arm in <b>adduction + internal rotation</b>!</li>\n</ul><h3><b>3. Pathophysiology &amp; Associated Structural Lesions</b></h3><ul>\n<li class=\"l1\"><b>Anterior:</b> Humeral head strips anterior-inferior labrum off glenoid (<b>Bankart Lesion</b>) and impacts against anterior glenoid rim creating a posterolateral humeral head dent (<b>Hill-Sachs Lesion</b>). Stretches the <b>Axillary Nerve</b> (runs around surgical neck!).</li>\n<li class=\"l1\"><b>Posterior:</b> Humeral head locks behind posterior glenoid (<b>Reverse Hill-Sachs Lesion</b>).</li>\n</ul><h3><b>4. Clinical Picture (CRITICAL EXAM SIGNS!)</b></h3><ul>\n<li class=\"l1\"><b>Anterior Dislocation:</b> Patient holds arm <mark class=\"hl lab\"><b>slightly ABDUCTED &amp; EXTERNALLY ROTATED</b></mark> , refuses to move it; <b>loss of normal rounded deltoid contour (\"Squared-Off Shoulder\")</b>, prominent lateral acromion, palpable anterior fullness below coracoid!</li>\n<li class=\"l2\"><b>MANDATORY PRE- &amp; POST-REDUCTION NEURO EXAM:</b> Test <b>Axillary Nerve</b> (<b>Sensation over \"Regimental Badge\" area</b> of lateral deltoid + deltoid contraction!) and radial pulse!</li>\n<li class=\"l1\"><b>Posterior Dislocation:</b> Arm is <b>LOCKED IN ADDUCTION &amp; INTERNAL ROTATION</b> (<b>patient CANNOT externally rotate arm passively or actively!</b>), prominent posterior shoulder, flattened anterior shoulder!</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Trauma Shoulder X-Ray Series (3 Views — NEVER rely on AP alone!):</b></li>\n<li class=\"l2\"><b>AP</b>, <b>Scapular Y-View</b>, and <b>Axillary View</b> (or Velpeau view)!</li>\n<li class=\"l2\"><i>Anterior X-Ray:</i> Humeral head lies <b>inferior &amp; medial</b> to glenoid (subcoracoid).</li>\n<li class=\"l2\"><i>Posterior X-Ray Trap:</i> AP view can look deceptively normal! Look for <b>\"Lightbulb Sign\"</b> (internally rotated humeral head looks symmetrical like a lightbulb!) + vacant glenoid -&gt; <b>Axillary/Scapular-Y view confirms posterior displacement!</b></li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Proximal humerus fracture (especially surgical neck!), AC joint separation, Rotator cuff tear, Clavicle fracture.</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\"><b>Recurrent Instability / Dislocation</b> (very high ~70–90% in young athletes &lt; 20 yrs!), <b>Axillary Nerve Injury (~5–15%)</b>, Rotator cuff tear (especially <b>patients &gt; 40 years old</b>!), <b>Hill-Sachs / Bankart lesions</b>, Axillary artery injury (elderly atherosclerotic!).</li>\n</ul><h3><b>8. Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Prompt Closed Reduction (After Confirming No Displaced Neck Fracture on X-Ray!):</b></span></p>\n<ul>\n<li class=\"l2\">Give adequate <b>Procedural Sedation + Analgesia</b> (or intra-articular Lidocaine!).</li>\n<li class=\"l2\">Techniques: <b>Stimson</b> (prone with weight), <b>Milch</b>, <b>FARES</b>, or <b>Traction-Countertraction</b> <i>(avoid violent Hippocratic foot-in-axilla method -&gt; brachial plexus injury!)</i>.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Post-Reduction Mandatory Checks:</b> Repeat <b>Axillary Nerve + Radial Pulse exam</b> AND obtain <b>Post-Reduction X-Rays</b> to confirm concentric reduction!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Immobilization &amp; Rehab:</b> <b>Sling</b> for 1–3 weeks + early pendulum/rotator cuff strengthening; <b>Arthroscopic Bankart Repair</b> recommended for recurrent dislocations or high-risk young athletes!</span></p>\n<p>[Image Reference Suggestion]: Shoulder X-Rays comparing <b>Anterior Dislocation (Subcoracoid)</b> vs. <b>Posterior Dislocation (\"Lightbulb Sign\" + Axillary View)</b>.</p><nav class=\"un\"><button class=\"nv\" data-u=\"u325\">← Case 2</button><button class=\"nv\" data-u=\"u327\">Case 4 →</button></nav></article><article class=\"view unit\" id=\"u327\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 4</span><h1>Proximal Humerus &amp; Humeral Shaft Fractures</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Proximal+Humerus+%26+Humeral+Shaft+Fractures\">🔍 Search on Google</a></header><h3><b>A. Proximal Humerus Fracture</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> <b>FOOSH</b> in <b>elderly osteoporotic females</b> (#1!) or high-energy trauma in young adults.</li>\n<li class=\"l1\"><b>Classification (Neer System):</b> Based on displacement (&gt; 1 cm or &gt; 45° angulation) of <b>4 anatomical parts</b>: Humeral head (anatomic neck), Surgical neck, Greater tuberosity, Lesser tuberosity (<b>~80% are non-displaced/1-part</b>!).</li>\n<li class=\"l1\"><b>Clinical &amp; Neuro Check:</b> Massive bruising tracking down chest wall &amp; arm (<b>Hennepin’s hematoma</b>), painful shoulder; check <b>Axillary Nerve</b> (especially in surgical neck fractures!).</li>\n<li class=\"l1\"><b>Treatment:</b> <b>~80% (Minimally Displaced) -&gt; Sling + Early Pendulum Exercises at 1–2 wks!</b> Displaced 2/3-part -&gt; <b>ORIF</b> (locking plate) or <b>IM Nail</b>; Elderly 3/4-part / head-split -&gt; <b>Reverse Total Shoulder Arthroplasty</b> (or Hemiarthroplasty)!</li>\n</ul><h3><b>B. Humeral Shaft Fracture (CLASSIC TEST &amp; CLINICAL PEARL: RADIAL NERVE PALSY!)</b></h3><ul>\n<li class=\"l1\"><b>Etiology (Separated):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Direct blow</b> to mid-arm (transverse/comminuted).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Twisting / Arm-Wrestling / Throwing Injury</b> (<b>Spiral fracture of distal-third = \"Holstein-Lewis Fracture\"</b> — highest risk of trapping Radial Nerve!).</span></p>\n<ul>\n<li class=\"l1\"><b>Clinical Picture:</b> Pain, swelling, shortening/angulation of upper arm, palpable crepitus.</li>\n<li class=\"l1\"><b>MANDATORY EXAM — RADIAL NERVE ASSESSMENT (Runs in Spiral Groove!):</b></li>\n<li class=\"l2\"><b>Motor:</b> <b>Wrist Drop</b> (inability to extend wrist — <b>ECRL/ECRB</b>), inability to extend fingers at <b>MCP</b> (Metacarpophalangeal) joints, and weak thumb extension/abduction!</li>\n<li class=\"l2\"><b>Sensory:</b> Numbness over <b>Dorsal First Webspace</b> (between thumb &amp; index finger)!</li>\n<li class=\"l1\"><b>Investigations:</b> AP &amp; Lateral X-Rays of <b>entire humerus (including shoulder &amp; elbow!)</b>.</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><b>&gt; 90% Heal Non-Operatively!</b> Gravity traction hangs align the shaft -&gt; <b>Coaptation Splint (\"U-Slab\")</b> initially for 1–2 weeks -&gt; switch to <b>Functional Humeral Brace (Sarmiento Brace)</b>! <i>(Acceptable alignment: &lt; 20° anterior, &lt; 30° varus, &lt; 3 cm shortening!).</i></li>\n<li class=\"l2\"><b>CRITICAL RADIAL NERVE RULE:</b> <mark class=\"hl dx\"><b>Primary Radial Nerve Palsy at time of closed humeral shaft fracture is usually a NEURAPRAXIA (~85–90% recover spontaneously within 3–6 months!) -&gt; OBSERVE with dynamic wrist-extension splint! Do NOT rush to surgical exploration UNLESS it is an OPEN fracture, vascular injury, or nerve palsy develops AFTER closed manipulation!</b></mark></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u326\">← Case 3</button><button class=\"nv\" data-u=\"u328\">Case 5 →</button></nav></article><article class=\"view unit\" id=\"u328\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 5</span><h1>Pediatric Supracondylar Humerus Fracture</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Supracondylar+Humerus+Fracture\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Epidemiology</b></h3><p>Extra-articular fracture of the distal humerus just above the epicondyles (<b>#1 Most Common Pediatric Elbow Fracture</b>, peaking at <b>5–7 years</b>!). <mark class=\"hl mech\"><b>HIGHEST RISK OF CATASTROPHIC NEUROVASCULAR COMPLICATIONS IN PEDIATRIC ORTHOPEDICS!</b></mark></p><h3><b>2. Etiology (Separated — Extension vs. Flexion Type)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Extension-Type (~95–98%):</b> <b>FOOSH</b> with elbow hyperextended (distal fragment displaces <b>POSTERIORLY</b>).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Flexion-Type (~2–5%):</b> Direct fall onto a flexed elbow (distal fragment displaces <b>ANTERIORLY</b> -&gt; <b>Ulnar Nerve</b> injury!).</span></p><h3><b>3. Clinical Picture (CHECK PULSE, PERFUSION &amp; ALL 3 NERVES!)</b></h3><ul>\n<li class=\"l1\">Refusal to move arm, severe elbow swelling, <b>\"S-shaped\" deformity</b>, <b>Pucker Sign</b> (anterior skin dimpling when proximal spike pierces brachialis muscle — irreducible!).</li>\n<li class=\"l1\"><b>Gartland Classification (Extension Type):</b></li>\n<li class=\"l2\"><i>Type I:</i> Non-displaced (often ONLY visible as <b>\"Posterior Fat Pad Sign\"</b> on lateral X-ray!).</li>\n<li class=\"l2\"><i>Type II:</i> Displaced with intact posterior cortex.</li>\n<li class=\"l2\"><i>Type III:</i> <b>Completely displaced</b> with NO cortical contact (<b>HIGHEST complication rate!</b>).</li>\n<li class=\"l1\"><b>MANDATORY NERVE &amp; VASCULAR EXAM:</b></li>\n<li class=\"l2\"><b>AIN</b> (Anterior Interosseous Nerve — branch of <b>Median Nerve — #1 MOST COMMONLY INJURED NERVE in Extension-Type!</b>): Test <b>\"OK Sign\"</b> (flexion of thumb IP [Interphalangeal] + index DIP [Distal Interphalangeal] joints — inability = flat pinch!).</li>\n<li class=\"l2\"><b>Radial Nerve (#2):</b> Wrist/thumb extension + dorsal 1st webspace.</li>\n<li class=\"l2\"><b>Ulnar Nerve (Flexion-type or K-wire pin injury):</b> Finger abduction (crossing fingers), sensation 5th digit.</li>\n<li class=\"l2\"><b>Brachial Artery:</b> Check <b>Radial Pulse &amp; Hand Perfusion</b> (warm pink hand + brisk capillary refill!).</li>\n</ul><h3><b>4. Investigations (CRITICAL X-RAY LINES ON LATERAL ELBOW!)</b></h3><ul>\n<li class=\"l1\"><b>AP &amp; Lateral Elbow X-Rays:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Anterior Humeral Line:</b> Normally bisects the <b>middle third of the Capitellum</b>; in extension supracondylar fracture, it passes <i>anterior</i> to capitellum!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Baumann’s Angle</b> (on AP view: 70–75°; assesses varus/valgus).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Posterior Fat Pad Sign (\"Sail Sign\"):</b> Always pathologic — indicates occult intra-articular elbow fracture even if no fracture line is seen!</span></p><h3><b>5. Complications (DO NOT MISS!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Brachial Artery Injury / Acute Compartment Syndrome -&gt; Volkmann’s Ischemic Contracture</b></mark> (permanent claw-hand deformity from forearm flexor necrosis!).</li>\n<li class=\"l1\"><b>Cubitus Varus (\"Gunstock Deformity\")</b> — most common late complication from malunion!</li>\n<li class=\"l1\">Nerve palsies (AIN, Radial, Ulnar — mostly neurapraxias recovering in 2–4 months).</li>\n</ul><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Gartland Type I:</b> <b>Long-Arm Posterior Splint/Cast</b> at 90° flexion × 3 weeks.</li>\n<li class=\"l1\"><b>Gartland Type II &amp; III (Displaced):</b> <mark class=\"hl mech\"><b>Urgent Closed Reduction &amp; Percutaneous Pinning (CRPP with 2–3 Lateral K-Wires — avoids medial ulnar nerve!)</b></mark> under anesthesia!</li>\n<li class=\"l1\"><mark class=\"hl dx\"><b>PULSELESS HAND RULE:</b></mark></li>\n<li class=\"l2\"><i>\"Pink Pulseless Hand\" (absent pulse, warm pink capillary refill &lt; 2 sec):</i> <mark class=\"hl mech\"><b>Urgent CRPP FIRST</b></mark> (pulse usually returns once bone kink is relieved!), then monitor closely!</li>\n<li class=\"l2\"><i>\"White/Cold Pulseless Hand\" (ischemic):</i> <mark class=\"hl mech\"><b>Emergent CRPP</b></mark> -&gt; if still cold/white after reduction -&gt; <mark class=\"hl rx\"><b>Immediate Vascular Exploration/Repair + Forearm Fasciotomy</b></mark> !</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u327\">← Case 4</button><button class=\"nv\" data-u=\"u329\">Case 6 →</button></nav></article><article class=\"view unit\" id=\"u329\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 6</span><h1>Elbow Dislocation, Radial Head Fracture &amp; Nursemaidʼs Elbow</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Elbow+Dislocation%2C+Radial+Head+Fracture+%26+Nursemaid%CA%BCs+Elbow\">🔍 Search on Google</a></header><h3><b>A. Adult Elbow Dislocation (90% Posterior!)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> FOOSH with elbow slightly flexed -&gt; olecranon driven posteriorly behind distal humerus.</li>\n<li class=\"l1\"><b>Signs:</b> Markedly swollen flexed elbow, <b>loss of normal equilateral triangle</b> (olecranon + medial &amp; lateral epicondyles!). Check <b>Ulnar/Median nerves &amp; Brachial artery</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> Rule out associated radial head/coronoid fractures (\"Terrible Triad\" if Elbow dislocation + Radial head fx + Coronoid fx!) -&gt; <b>Closed Reduction under sedation</b> -&gt; brief splint (&lt; 1–2 wks) -&gt; <b>early ROM</b> (Range of Motion) to prevent permanent elbow stiffness!</li>\n</ul><h3><b>B. Radial Head Fracture</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> FOOSH with axial load driving radial head into capitellum.</li>\n<li class=\"l1\"><b>Signs:</b> Focal tenderness over <b>lateral elbow (radial head)</b>, <b>pain on forearm pronation/supination</b>, positive <b>Posterior Fat Pad Sign</b> on X-ray!</li>\n<li class=\"l1\"><b>Treatment:</b> <i>Non-displaced (Mason I):</i> <b>Sling + Immediate Early Motion</b> (aspirate hemarthrosis + inject lidocaine for comfort!). <i>Displaced/Mechanical block to rotation (Mason II–III):</i> <b>ORIF</b> (headless screws) or <b>Radial Head Arthroplasty</b> (do NOT simply excise if MCL/DRUJ unstable -&gt; <b>Essex-Lopresti</b>!).</li>\n</ul><h3><b>C. Nursemaid’s Elbow (Radial Head Subluxation — Pediatric Classic!)</b></h3><ul>\n<li class=\"l1\"><b>Age &amp; Mechanism:</b> Toddlers (<b>1 – 4 Years</b>) after <b>sudden axial traction on an extended, pronated arm</b> (e.g., parent pulling child up by hand from curb or swinging by arms!) -&gt; annular ligament slips over radial head!</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Child cries briefly, then sits calmly <b>holding arm slightly flexed and PRONATED against side, refusing to use the hand</b>! <b>NO swelling, NO bruising, NO bony tenderness!</b></li>\n<li class=\"l1\"><b>Investigations:</b> <b>NO X-RAY NEEDED</b> if classic history and no swelling/deformity!</li>\n<li class=\"l1\"><b>Curative Treatment:</b> <b>Hyperpronation Maneuver</b> (or <b>Supination-Flexion Maneuver</b>) -&gt; feel/hear a subtle <b>click</b> -&gt; child uses arm normally within <b>10–15 minutes</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u328\">← Case 5</button><button class=\"nv\" data-u=\"u330\">Case 7 →</button></nav></article><article class=\"view unit\" id=\"u330\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 7</span><h1>Forearm Fractures (MONTEGGIA VS. GALEAZZI VS. BOTH-BONE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Forearm+Fractures+%28MONTEGGIA+VS.+GALEAZZI+VS.+BOTH-BONE%29\">🔍 Search on Google</a></header><p><i>(CRITICAL ORTHOPEDIC RULE: Because the radius and ulna form a rigid ring, </i><i><b>an isolated shaft fracture of ONE bone is almost ALWAYS accompanied by a dislocation of the proximal or distal radioulnar joint</b></i><i> — ALWAYS X-ray both Elbow and Wrist!)</i></p><h4><b>High-Yield Comparison (Mnemonic: \"M-U-G-R\")</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Monteggia Fracture-Dislocation</b></p></th><th><p><b>Galeazzi Fracture-Dislocation</b></p></th></tr><tr><td><p><b>Definition</b></p></td><td><p>Fracture of <b>PROXIMAL ULNA</b> + <b>Dislocation of RADIAL HEAD</b> at Elbow!</p></td><td><p>Fracture of <b>DISTAL/MID RADIUS</b> + <b>Dislocation of DRUJ</b> (Distal Radioulnar Joint) at Wrist!</p></td></tr><tr><td><p><b>Mnemonic</b></p></td><td><p><b>\"M-U\"</b> = <b>M</b>onteggia = <b>U</b>lna fracture</p></td><td><p><b>\"G-R\"</b> = <b>G</b>aleazzi = <b>R</b>adius fracture</p></td></tr><tr><td><p><b>Mechanism</b></p></td><td><p>FOOSH with forced pronation, or direct blow protecting head (\"Nightstick\")</p></td><td><p>FOOSH with hyperpronated forearm</p></td></tr><tr><td><p><b>Classic Nerve Injury</b></p></td><td><p><b>PIN</b> (Posterior Interosseous Nerve — branch of <b>Radial Nerve</b> -&gt; inability to extend fingers/thumb at MCP, <b>NO wrist drop &amp; NO sensory loss!</b>)</p></td><td><p>Anterior Interosseous / Ulnar nerve (rare)</p></td></tr><tr><td><p><b>Treatment (Adults)</b></p></td><td><p><b>ORIF of Ulna</b> (anatomic plating restores radial head alignment!)</p></td><td><p><b>ORIF of Radius</b> (+/- DRUJ pinning/splinting in supination — <b>\"Fracture of Necessity\"</b>!)</p></td></tr></table><ul>\n<li class=\"l1\"><b>Adult Both-Bone Forearm Fracture:</b> Treated as an intra-articular joint (must restore radial bow!) -&gt; <b>Surgical ORIF (Compression Plating) of BOTH Radius and Ulna</b>! (In young <b>children</b>, closed reduction + long-arm cast usually heals well!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u329\">← Case 6</button><button class=\"nv\" data-u=\"u331\">Case 8 →</button></nav></article><article class=\"view unit\" id=\"u331\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 8</span><h1>Distal Radius Fractures (COLLESʼ VS. SMITHʼS VS. BARTONʼS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Distal+Radius+Fractures+%28COLLES%CA%BC+VS.+SMITH%CA%BCS+VS.+BARTON%CA%BCS%29\">🔍 Search on Google</a></header><h3><b>1. Definitions &amp; Comparison (#1 Most Common Fracture in Adults / Elderly Osteoporotic Females!)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Type</b></p></th><th><p><b>Mechanism</b></p></th><th><p><b>Displacement of Distal Fragment</b></p></th><th><p><b>Classic Deformity / Pearl</b></p></th></tr><tr><td><p><b>Colles’ Fracture</b> <i>(#1 Overall!)</i></p></td><td><p><b>FOOSH</b> (wrist extended/dorsiflexed)</p></td><td><p><b>DORSAL displacement &amp; Dorsal angulation </b>+ radial shortening</p></td><td><p><b>\"Dinner-Fork\" Deformity</b> (extra-articular distal radius within 2–3 cm of wrist)</p></td></tr><tr><td><p><b>Smith’s Fracture</b> <i>(\"Reverse Colles'\")</i></p></td><td><p>Fall onto <b>FLEXED</b> wrist (or blow to back of wrist)</p></td><td><p><b>VOLAR (palmar) displacement &amp; Volar angulation</b></p></td><td><p><b>\"Garden-Spade\" Deformity</b> (unstable -&gt; often needs <b>Volar Locking Plate ORIF</b>!)</p></td></tr><tr><td><p><b>Barton’s Fracture</b></p></td><td><p>High-energy shear trauma</p></td><td><p><b>Intra-articular</b> dorsal/volar rim fracture-dislocation of radiocarpal joint</p></td><td><p>Unstable joint subluxation -&gt; <b>Requires ORIF!</b></p></td></tr></table><h3><b>2. Clinical Exam &amp; Investigations</b></h3><ul>\n<li class=\"l1\">Swollen painful wrist, deformity; <b>MUST check Median Nerve function</b> (thumb/index/middle palmar sensation + thumb abduction — acute <b>Carpal Tunnel Syndrome </b>occurs in ~5–10%!).</li>\n<li class=\"l1\"><b>AP &amp; Lateral Wrist X-Rays:</b> Check Radial Height (11–12 mm), Radial Inclination (22–23°), and Volar Tilt (normal 11°).</li>\n</ul><h3><b>3. Complications</b></h3><ul>\n<li class=\"l1\"><b>Acute Carpal Tunnel Syndrome</b> (Median nerve compression — urgent carpal tunnel release if progressive!), <mark class=\"hl mech\"><b>CRPS</b></mark> (Complex Regional Pain Syndrome), <b>EPL </b>(Extensor Pollicis Longus) <b>Tendon Rupture</b> (delayed weeks later!), Malunion, Post-traumatic wrist arthritis.</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Colles’ Fracture (Extra-Articular, Stable):</b> Hematoma block / sedation -&gt; <b>Closed Reduction</b> (traction + volar flexion + ulnar deviation) + <b>Sugar-Tong Splint / Short-Arm Cast</b> for 6 weeks -&gt; repeat X-rays at 1 &amp; 2 weeks to catch re-displacement!</li>\n<li class=\"l1\"><b>Unstable / Comminuted / Intra-Articular / Failed Reduction / Smith’s / Barton’s:</b> <b>ORIF with Volar Locking Plate</b> (allows early wrist motion!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u330\">← Case 7</button><button class=\"nv\" data-u=\"u332\">Case 9 →</button></nav></article><article class=\"view unit\" id=\"u332\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 9</span><h1>Scaphoid Fracture &amp; Boxerʼs Fracture</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Scaphoid+Fracture+%26+Boxer%CA%BCs+Fracture\">🔍 Search on Google</a></header><h3><b>A. Scaphoid Fracture (#1 Most Common Carpal Bone Fracture!)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> <b>FOOSH</b> with hyperextended, radially deviated wrist (classic in young adult males!).</li>\n<li class=\"l1\"><b>Pathophysiology — CRITICAL BLOOD SUPPLY RULE:</b> Blood enters the scaphoid <mark class=\"hl lab\"><b>DISTALLY</b></mark> (from radial artery dorsal branch) and flows <b>RETROGRADE</b> to the proximal pole! Therefore, <b>proximal pole / waist fractures cut off blood supply -&gt; high risk of AVN (Avascular Necrosis) &amp; Nonunion!</b></li>\n<li class=\"l1\"><b>Clinical Picture (THE GOLDEN DIAGNOSTIC RULE!):</b></li>\n<li class=\"l2\">Mild wrist ache after FOOSH + <mark class=\"hl lab\"><b>TENDERNESS IN THE \"ANATOMICAL SNUFFBOX\"</b></mark> (between EPL and EPB/APL tendons) + <b>Pain on Axial Loading of the Thumb</b>!</li>\n<li class=\"l2\"><b>CRITICAL X-RAY TRAP:</b> Initial Scaphoid X-Rays are <mark class=\"hl lab\"><b>FALSELY NEGATIVE in ~15–20%</b></mark> of acute fractures!</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Clinically Suspected (Snuffbox Tenderness) Even With </i><i><b>NORMAL X-Rays</b></i><i>:</i> <mark class=\"hl mech\"><b>IMMOBILIZE IN A THUMB SPICA SPLINT/CAST</b></mark> and repeat X-rays in <b>10–14 days</b> (or obtain <mark class=\"hl mech\"><b>MRI Wrist</b></mark> immediately to confirm/rule out!).</li>\n<li class=\"l2\"><i>Confirmed Non-Displaced Waist/Distal Fracture:</i> <b>Thumb Spica Cast</b> for 6–12 weeks!</li>\n<li class=\"l2\"><i>Displaced (&gt; 1 mm), Proximal Pole, or Nonunion:</i> <b>ORIF with Headless Compression Screw (Herbert Screw)</b>!</li>\n</ul><h3><b>B. Boxer’s Fracture (5th Metacarpal Neck Fracture)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Punching a wall or hard object with a <b>closed fist</b>!</li>\n<li class=\"l1\"><b>Signs:</b> Pain, swelling over ulnar dorsal hand, <b>loss of 5th knuckle prominence</b>! <b>CRITICAL CHECK:</b> Inspect skin over knuckle for tooth laceration (<b>\"Fight Bite\"</b> -&gt; high risk of <i>Eikenella corrodens</i> septic MCP arthritis -&gt; surgical washout + <mark class=\"hl rx\"><b>Amoxicillin-Clavulanate</b></mark> !), AND check for <b>Malrotation</b> (ask patient to flex fingers — all fingers must point toward scaphoid without overlapping/scissoring!).</li>\n<li class=\"l1\"><b>Treatment:</b> Up to <b>30–40° volar angulation is acceptable</b> (5th CMC is mobile!) -&gt; <b>Ulnar Gutter Splint</b> (\"intrinsic-plus\" safe position: MCP flexed 70–90°, IP extended!) × 3–4 weeks! <b>Operate (K-wires/ORIF) ONLY if ANY Rotational Deformity (\"scissoring\") or &gt; 40° angulation!</b></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u331\">← Case 8</button><button class=\"nv\" data-u=\"u333\">Case 10 →</button></nav></article><article class=\"view unit\" id=\"u333\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 10</span><h1>Trigger Finger, DE Quervainʼs Tenosynovitis &amp; Mallet / Jersey Finger</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Trigger+Finger%2C+DE+Quervain%CA%BCs+Tenosynovitis+%26+Mallet+%2F+Jersey+Finger\">🔍 Search on Google</a></header><h4><b>High-Yield Hand &amp; Tendon Disorders in Outpatient Clinics</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Condition</b></p></th><th><p><b>Pathophysiology &amp; Tendon Involved</b></p></th><th><p><b>Classic Presentation &amp; Exam Sign</b></p></th><th><p><b>Treatment</b></p></th></tr><tr><td><p><b>Trigger Finger</b> <i>(Stenosing Tenosynovitis)</i></p></td><td><p>Thickening/inflammation of flexor tendon sheath at <b>A1 Pulley</b> (common in <b>Diabetics, RA, females</b>!)</p></td><td><p>Painful <b>\"catching/locking\" of finger in flexion </b>that snaps open painfully; <b>tender nodule over palmar MCP crease</b></p></td><td><p>Rest/splint -&gt; <b>Corticosteroid Injection into A1 pulley sheath (~70–90% cure!)</b> -&gt; Surgical <b>A1 Pulley Release</b> if refractory!</p></td></tr><tr><td><p><b>De Quervain’s Tenosynovitis</b></p></td><td><p>Stenosing tenosynovitis of <b>1st Dorsal Compartment</b> (<b>APL</b> [Abductor Pollicis Longus] &amp; <b>EPB</b> [Extensor Pollicis Brevis])</p></td><td><p>Radial wrist pain radiating up forearm in <b>new mothers lifting infants</b>, gamers, text-users; <b>POSITIVE FINKELSTEIN’S TEST</b> (tuck thumb inside fist &amp; ulnar-deviate wrist -&gt; sharp pain!)</p></td><td><p><b>Thumb Spica Splint</b> + NSAIDs -&gt; <b>Corticosteroid Injection</b> -&gt; Surgical 1st compartment release if refractory!</p></td></tr><tr><td><p><b>Mallet Finger</b></p></td><td><p>Disruption of <b>Terminal Extensor Tendon </b>insertion at <b>DIP</b> (Distal Interphalangeal) joint (ball hitting fingertip!)</p></td><td><p><b>Inability to actively extend DIP joint (\"drooping fingertip\")</b> (passively extends normally!)</p></td><td><p><b>Continuous Full-Time Extension Splinting of DIP ONLY</b> (leave PIP free!) <b>for 6–8 FULL WEEKS</b> (if finger drops once during change, clock resets to Day 0!)</p></td></tr><tr><td><p><b>Jersey Finger</b></p></td><td><p>Avulsion of <b>FDP</b> (Flexor Digitorum Profundus) from distal phalanx (classic: <b>Ring finger </b>catching opponent’s jersey!)</p></td><td><p><b>Inability to actively flex DIP joint</b> while PIP is held extended</p></td><td><p><b>URGENT Surgical Tendon Repair (Within 7–10 Days!)</b> before tendon retracts into palm!</p></td></tr></table><p class=\"muted\"><i>End of Part 13A — Orthopedics (Cases 1–10 Complete!).</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u332\">← Case 9</button><button class=\"nv\" data-u=\"u334\">Case 11 →</button></nav></article><article class=\"view unit\" id=\"u334\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 11</span><h1>Pelvic Ring Fractures &amp; Acetabular Fractures</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pelvic+Ring+Fractures+%26+Acetabular+Fractures\">🔍 Search on Google</a></header><h3><b>1. Definitions</b></h3><ul>\n<li class=\"l1\"><b>Pelvic Ring Fracture:</b> Disruption of the osseous-ligamentous pelvic ring (sacrum, ilium, ischium, pubis), often associated with <b>life-threatening retroperitoneal hemorrhage</b> and urogenital injury.</li>\n<li class=\"l1\"><b>Acetabular Fracture:</b> Intra-articular fracture of the hip socket (posterior wall, anterior/posterior column), threatening hip stability and cartilage integrity.</li>\n</ul><h3><b>2. Etiology (Separated — High-Energy vs. Low-Energy)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>High-Energy Trauma (Young Adults — High Mortality!):</b></span></p>\n<ul>\n<li class=\"l2\"><b>AP</b> (Anteroposterior) <b>Compression (\"Open-Book\" Injury):</b> Head-on <b>MVC</b> (Motor Vehicle Collision) or motorcycle crash -&gt; disrupts pubic symphysis and anterior <b>SI</b> (Sacroiliac) ligaments, increasing pelvic volume!</li>\n<li class=\"l2\"><b>Lateral Compression (Most Common Pelvic Fracture!):</b> Side-impact MVC or pedestrian struck -&gt; crushes iliac wing/pubic rami inward (less hemorrhage, higher <b>bladder/brain/visceral injury</b>!).</li>\n<li class=\"l2\"><b>Vertical Shear:</b> Fall from great height landing on one leg -&gt; disrupts anterior AND posterior SI ligaments vertically (<b>most unstable &amp; highest hemorrhage risk!</b>).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Low-Energy Trauma (Elderly Osteoporotic Patients):</b> Simple fall from standing height causing isolated <b>pubic rami fractures</b> (stable ring, low hemorrhage risk).</span></p><h3><b>3. Pathophysiology</b></h3><p>Because the pelvis is a closed ring, displacement at one site almost always implies disruption elsewhere. Major bleeding (<b>&gt; 2–4 Liters</b>) arises primarily from the <b>presacral/retroperitoneal venous plexus (~85%)</b>, fractured cancellous bone surfaces, and branches of the <b>Internal Iliac Artery (~15%)</b> (Superior Gluteal Artery!).</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Severe pelvic/groin pain, inability to bear weight, leg-length discrepancy, <b>ecchymosis over flanks/perineum/scrotum/labia</b>, hemorrhagic shock (Class III–IV).</li>\n<li class=\"l1\"><mark class=\"hl dx\"><b>CRITICAL PHYSICAL EXAM RULES:</b></mark></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Gently compress the pelvis ONCE ONLY</b> — <b>NEVER repeatedly \"rock\" the pelvis</b>, as it dislodges fragile retroperitoneal clots and restarts fatal bleeding!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>ALWAYS inspect the Perineum, Urethral Meatus, Vagina, and Rectum (DRE</b> [Digital Rectal Exam] + <b>Vaginal Speculum Exam</b>) to rule out <b>Open Pelvic Fracture </b>(~50% mortality!) and <b>Urethral/Bladder Injury</b> (<b>blood at urethral meatus, high-riding prostate, scrotal/perineal hematoma</b>)!</span></p><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Primary Survey Stat Imaging:</b> <b>AP Pelvic X-Ray</b> (during <b>ATLS</b> [Advanced Trauma Life Support] trauma bay resuscitation!) + <mark class=\"hl mech\"><b>eFAST</b></mark> (Extended Focused Assessment with Sonography for Trauma — rule out concurrent intraperitoneal blood!).</li>\n<li class=\"l1\"><b>If Urethral Injury Signs Exist:</b> Perform <b>RUG</b> (Retrograde Urethrogram) <mark class=\"hl rx\"><b>BEFORE inserting a Foley catheter!</b></mark> (If intact -&gt; <b>CT</b> [Computed Tomography] <b>Cystogram</b> if gross hematuria to check for intraperitoneal vs. extraperitoneal bladder rupture!).</li>\n<li class=\"l1\"><b>Definitive Orthopedic Mapping:</b> <b>Contrast-Enhanced CT Pelvis</b> (with 3D reconstruction + arterial blush check).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Hip dislocation, Femoral neck/intertrochanteric fracture, Intraperitoneal solid organ rupture (spleen/liver), Lumbar spine fracture, Isolated soft-tissue contusion.</li>\n</ul><h3><b>7. Complications (Separated — Early vs. Late)</b></h3><ul>\n<li class=\"l1\"><b>Early Life-Threatening:</b> <b>Exsanguinating Retroperitoneal Hemorrhage</b>, <b>Urethral/Bladder Rupture</b>, <b>Open Pelvic Sepsis</b>, <b>Sciatic / Lumbosacral Plexus Injury</b>, <mark class=\"hl lab\"><b>DVT/PE</b></mark> (Deep Vein Thrombosis / Pulmonary Embolism — extremely high risk!).</li>\n<li class=\"l1\"><b>Late:</b> Pelvic malunion/nonunion, chronic <b>SI</b> joint pain, post-traumatic hip osteoarthritis (acetabular fractures), sexual dysfunction / urethral stricture.</li>\n</ul><h3><b>8. Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Immediate Hemorrhage Control (ATLS Protocol):</b></span></p>\n<ul>\n<li class=\"l2\">Apply a <b>Pelvic Binder</b> (or tightly tied bedsheet) centered <b>OVER THE GREATER TROCHANTERS</b> (NOT the iliac crests!) -&gt; closes \"open-book\" volume and tamponades venous bleeding!</li>\n<li class=\"l2\">Aggressive <b>Massive Transfusion Protocol (1:1:1 Packed RBCs : FFP</b> [Fresh Frozen Plasma] <b>: Platelets)</b> + <b>IV TXA</b> (Tranexamic Acid).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl mech\"><b>Ongoing Shock Despite Pelvic Binder (After Ruling Out Chest/Abdominal Hemorrhage on eFAST!):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><b>Angioembolization</b> (for arterial blush on CT) and/or <b>Preperitoneal Pelvic Packing + Emergent External Fixation</b>!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Definitive Orthopedic Care:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Stable Elderly Pubic Rami:</i> Early mobilization with walker + analgesia!</li>\n<li class=\"l2\"><i>Unstable Ring / Displaced Acetabular (&gt; 2 mm step-off):</i> <b>ORIF</b> (Open Reduction Internal Fixation) / percutaneous SI screws once hemodynamically stable!</li>\n</ul>\n<p><b>Clinical Pearl:</b> <i>A trauma patient in hemorrhagic shock with a negative eFAST and clear CXR is bleeding into the </i><i><b>Retroperitoneum from a Pelvic Fracture</b></i><i> until proven otherwise — bind the </i><i><b>greater trochanters</b></i><i> immediately!</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u333\">← Case 10</button><button class=\"nv\" data-u=\"u335\">Case 12 →</button></nav></article><article class=\"view unit\" id=\"u335\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 12</span><h1>HIP Dislocation (POSTERIOR VS. ANTERIOR)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=HIP+Dislocation+%28POSTERIOR+VS.+ANTERIOR%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Complete displacement of the <b>femoral head</b> out of the <b>acetabulum</b>. Because the hip is an inherently deep, stable ball-and-socket joint, native hip dislocation requires <b>massive high-energy force</b> (<b>Orthopedic Emergency — Must Reduce Within 6 Hours!</b>).</p><h3><b>2. Etiology (Separated by Direction!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Posterior Hip Dislocation (~90% — Most Common!):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Classic \"Dashboard Injury\":</b> Unbelted front-seat passenger in an <b>MVC</b> whose flexed knee strikes the dashboard, driving the femoral head posteriorly out of the acetabulum (often fracturing the posterior acetabular wall!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Anterior Hip Dislocation (~10%):</b></span></p>\n<ul>\n<li class=\"l2\">Forced <b>hyperabduction and external rotation</b> (e.g., motorcycle crash, gymnastics/ski fall).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Prosthetic Hip Dislocation (Low-Energy!):</b> Occurs after <b>THA</b> (Total Hip Arthroplasty) when bending/crossing legs past safe precautions (posterior approach -&gt; excessive flexion + internal rotation!).</span></p><h3><b>3. Pathophysiology</b></h3><p>Dislocation tears the joint capsule and <b>Ligamentum Teres</b>, severely kinking or stretching the <b>Medial Femoral Circumflex Artery (MFCA)</b> — the primary blood supply to the femoral head! Risk of <b>AVN</b> (Avascular Necrosis) rises sharply if reduction is delayed <b>&gt; 6–12 hours</b>.</p><h3><b>4. Clinical Picture (Classic Opposite Limb Positions!)</b></h3><ul>\n<li class=\"l1\"><b>Posterior Dislocation:</b> Leg is <mark class=\"hl lab\"><b>SHORTENED, ADDUCTED, AND INTERNALLY ROTATED</b></mark> (<b>\"SAID\"</b> — <b>S</b>hortened, <b>A</b>dducted, <b>I</b>nternally rotated <b>D</b>islocation; knee rests against opposite thigh!).</li>\n<li class=\"l2\"><i>Mandatory Nerve Check:</i> <b>Sciatic Nerve Injury (~10–20%)</b> — specifically the <b>Peroneal Division</b> -&gt; <b>Weak Ankle Dorsiflexion (\"Foot Drop\")</b> + numbness on dorsum of foot!</li>\n<li class=\"l1\"><b>Anterior Dislocation:</b> Leg is <mark class=\"hl lab\"><b>ABDUCTED, EXTERNALLY ROTATED, AND FLEXED</b></mark> (looks open/frogged out!).</li>\n<li class=\"l2\"><i>Mandatory Neurovascular Check:</i> <b>Femoral Nerve &amp; Femoral Artery/Vein</b>!</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>AP Pelvis + Cross-Table Lateral Hip X-Rays</b> (rule out concurrent <b>Femoral Neck Fracture</b> BEFORE attempting closed reduction — pulling on an occult femoral neck fracture displaces it catastrophically!).</li>\n<li class=\"l1\"><b>Post-Reduction CT Pelvis (MANDATORY!):</b> Checks for concentric reduction, <b>intra-articular loose bone fragments</b>, and <b>posterior wall acetabular fracture</b>!</li>\n<li class=\"l1\"><b>Check Ipsilateral Knee!</b> (\"Dashboard injury\" frequently causes concurrent <b>PCL</b> [Posterior Cruciate Ligament] tear, patellar fracture, or femoral shaft fracture!).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Femoral neck fracture (shortened &amp; <mark class=\"hl lab\"><b>EXTERNALLY</b></mark> rotated!), Intertrochanteric fracture (shortened &amp; <mark class=\"hl lab\"><b>EXTERNALLY</b></mark> rotated!), Pelvic fracture, Acetabular fracture without dislocation.</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\"><b>AVN</b> (Avascular Necrosis of femoral head — ~10% if reduced &lt; 6 hrs, &gt; 40–50% if &gt; 12 hrs!), <b>Sciatic Nerve Palsy</b>, <mark class=\"hl lab\"><b>Post-traumatic Hip Osteoarthritis</b></mark> (#1 late complication!), Recurrent dislocation, <b>Heterotopic Ossification</b>.</li>\n</ul><h3><b>8. Treatment</b></h3><ul>\n<li class=\"l1\"><b>EMERGENT CLOSED REDUCTION (Target &lt; 6 Hours!)</b> under deep IV conscious sedation or general anesthesia (<b>Allis / Stimson / Captain Morgan maneuver</b>).</li>\n<li class=\"l1\"><b>Urgent OR (Open Reduction) Indicated If:</b> Irreducible by closed means (buttonholed capsule/piriformis), <b>non-concentric reduction</b> (trapped bone fragment on post-reduction CT!), associated <b>femoral neck fracture</b>, or unstable large posterior acetabular wall fracture (&gt; 20–40%)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u334\">← Case 11</button><button class=\"nv\" data-u=\"u336\">Case 13 →</button></nav></article><article class=\"view unit\" id=\"u336\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 13</span><h1>Femoral Neck Fracture (INTRACAPSULAR HIP FRACTURE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Femoral+Neck+Fracture+%28INTRACAPSULAR+HIP+FRACTURE%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Fracture of the proximal femur between the femoral head and the intertrochanteric line, lying <b>INSIDE the hip joint capsule (Intracapsular)</b>.</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Low-Energy Fall in Elderly Osteoporotic Patients (~90% — Especially Females &gt; 65–70 Yrs):</b> Simple fall onto the side/greater trochanter.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>High-Energy Trauma (Young Adults &lt; 50 Yrs):</b> MVC or fall from height (<b>True Emergency to Save Native Head!</b>).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Stress / Pathologic Fractures:</b> Military recruits/runners (tension-side superior neck stress fracture) or bone metastases.</span></p><h3><b>3. Pathophysiology (CRITICAL BLOOD SUPPLY TRAP!)</b></h3><p>The femoral head is supplied predominantly by <b>retrograde retinacular vessels</b> from the <b>MFCA</b> (Medial Femoral Circumflex Artery) running upward <i>along the femoral neck inside the capsule</i>. Displaced fractures tear these vessels AND intra-articular hemarthrosis tamponades remaining flow -&gt; <b>HIGH RISK OF AVN &amp; NONUNION</b> (also no periosteum inside the capsule!).</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Displaced Fracture:</b> Elderly patient unable to stand/walk after a fall; affected leg is <mark class=\"hl lab\"><b>SHORTENED AND EXTERNALLY ROTATED</b></mark> ; pain in <b>groin</b> exacerbated by axial loading or log-rolling!</li>\n<li class=\"l1\"><b>Impacted / Non-Displaced (Garden I) Trap:</b> Patient may still be able to limp/bear weight with mild groin pain -&gt; <b>do NOT miss!</b></li>\n</ul><h3><b>5. Investigations (Garden Classification I–IV)</b></h3><ul>\n<li class=\"l1\"><b>AP Pelvis + AP &amp; Cross-Table Lateral Hip X-Rays:</b></li>\n<li class=\"l2\"><i>Garden I:</i> Incomplete / valgus-impacted | <i>Garden II:</i> Complete, <b>non-displaced</b> | <i>Garden III:</i> Complete, partially displaced | <i>Garden IV:</i> Complete, <b>fully displaced</b>!</li>\n<li class=\"l1\"><b>GOLD STANDARD IF X-RAYS ARE NEGATIVE DESPITE HIGH CLINICAL SUSPICION (Inability to Bear Weight + Groin Pain):</b> <mark class=\"hl mech\"><b>MRI Hip</b></mark> (~99% sensitive within 24 hrs for occult femoral neck fracture!).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Intertrochanteric femur fracture, Pubic ramus fracture, Posterior hip dislocation (<b>internally</b> rotated!), Hip osteoarthritis flare, Trochanteric bursitis.</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\"><b>AVN of Femoral Head</b> (~15–30% in displaced fractures!), <b>Nonunion</b>, <mark class=\"hl lab\"><b>DVT/PE</b></mark> , Pressure ulcers, Pneumonia, UTIs, and <b>1-Year Mortality (~20–30% in elderly if surgery is delayed!)</b>.</li>\n</ul><h3><b>8. Treatment (Operate Within 24–48 Hours to Reduce Mortality!)</b></h3><ul>\n<li class=\"l1\"><b>Pre-Op:</b> Optimize medical status, <mark class=\"hl lab\"><b>DVT prophylaxis (LMWH</b></mark> [Low Molecular Weight Heparin]), analgesia (Femoral nerve block / Fascia iliaca block reduces delirium!).</li>\n<li class=\"l1\"><b>Surgical Choice (Separated by Age &amp; Displacement):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Non-Displaced (Garden I–II — Any Age) OR Displaced in Young Patients (&lt; 60–65 Yrs):</b> <b>URGENT Closed/Open Reduction + Internal Fixation</b> (<b>3 Cannulated Screws</b> or <b>Sliding Hip Screw</b> — preserves native hip joint!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Displaced (Garden III–IV) in Elderly (&gt; 65–70 Yrs):</b> <b>Hip Arthroplasty</b> (avoids AVN &amp; nonunion and allows <b>immediate full weight-bearing</b>!):</span></p>\n<ul>\n<li class=\"l1\"><i>Lower-demand / frail elderly:</i> <b>Hemiarthroplasty</b> (replaces femoral head only).</li>\n<li class=\"l1\"><i>Active independent elderly or pre-existing hip arthritis:</i> <b>THA</b> (Total Hip Arthroplasty)!</li>\n</ul>\n<p>[Image Reference Suggestion]: Diagram of <b>Proximal Femur Blood Supply (MFCA)</b> comparing <b>Intracapsular (Femoral Neck)</b> vs. <b>Extracapsular (Intertrochanteric) </b>fracture lines.</p><nav class=\"un\"><button class=\"nv\" data-u=\"u335\">← Case 12</button><button class=\"nv\" data-u=\"u337\">Case 14 →</button></nav></article><article class=\"view unit\" id=\"u337\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 14</span><h1>Intertrochanteric &amp; Subtrochanteric Femoral Fractures</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Intertrochanteric+%26+Subtrochanteric+Femoral+Fractures\">🔍 Search on Google</a></header><h3><b>1. Definitions</b></h3><ul>\n<li class=\"l1\"><b>Intertrochanteric Fracture:</b> <b>Extracapsular</b> fracture running between the greater and lesser trochanters.</li>\n<li class=\"l1\"><b>Subtrochanteric Fracture:</b> Fracture occurring within <b>5 cm distal to the lesser trochanter</b> (highest tensile/compressive muscle deforming forces in the body!).</li>\n</ul><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Intertrochanteric:</b> Elderly osteoporotic patients (slightly older than femoral neck patients!) after low-energy sideways fall.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Subtrochanteric:</b> High-energy trauma in young adults, OR <b>Atypical Bisphosphonate-Associated Femur Fracture</b> (elderly woman on <b>Alendronate &gt; 5 years</b> with prodromal thigh ache -&gt; transverse subtrochanteric fracture with lateral cortical beaking!).</span></p><h3><b>3. Pathophysiology</b></h3><p>Because these fractures are <mark class=\"hl lab\"><b>EXTRACAPSULAR</b></mark> , they lie in <b>well-vascularized cancellous bone</b> -&gt; <b>AVN and Nonunion are RARE</b>, <i>however</i> the large bleeding surface causes <b>markedly greater blood loss (up to 500–1,000 mL)</b> and <b>Varus Malunion</b> if unstable!</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Unable to bear weight, severe hip/thigh pain, <mark class=\"hl lab\"><b>MARKEDLY SHORTENED AND EXTERNALLY ROTATED LEG</b></mark> (more pronounced than femoral neck!), extensive <b>ecchymosis over lateral hip/thigh</b>!</li>\n</ul><h3><b>5. Investigations &amp; Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> <mark class=\"hl mech\"><b>CBC</b></mark> (Complete Blood Count — check Hb drop!), <mark class=\"hl rx\"><b>Type &amp; Cross-match</b></mark> , <b>BMP</b> (Basic Metabolic Panel), <mark class=\"hl mech\"><b>ECG</b></mark> (Electrocardiogram), <mark class=\"hl mech\"><b>CXR</b></mark> (Chest X-Ray) for pre-op medical clearance.</li>\n<li class=\"l1\"><b>Imaging:</b> AP Pelvis + AP/Lateral Femur X-Rays.</li>\n<li class=\"l1\"><b>DDx:</b> Femoral neck fracture, Femoral shaft fracture, Hip dislocation, Pelvic fracture.</li>\n</ul><h3><b>6. Complications</b></h3><ul>\n<li class=\"l1\">Significant acute blood loss/anemia, <b>Varus Collapse / Malunion</b>, Screw cut-out, DVT/PE, Delirium, Pneumonia.</li>\n</ul><h3><b>7. Treatment (Surgical Fixation Within 24–48 Hours for Early Mobilization!)</b></h3><ul>\n<li class=\"l1\"><b>Stable Intertrochanteric Fracture (Intact Posteromedial Cortex):</b> <b>DHS</b> (Dynamic / Sliding Hip Screw) OR <b>Cephalomedullary Nail</b>.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Unstable Intertrochanteric (Comminuted, Reverse Obliquity) &amp; ALL Subtrochanteric Fractures:</b></mark> <b>Long Cephalomedullary / Intramedullary Nail (e.g., PFNA / Gamma Nail)</b> (load-sharing device closer to mechanical axis!).</li>\n<li class=\"l1\"><i>Post-Op Mandatory:</i> <mark class=\"hl lab\"><b>DVT Prophylaxis (LMWH/DOAC × 28–35 days)</b></mark> + <mark class=\"hl lab\"><b>Osteoporosis Workup &amp; Treatment</b></mark> (<b>Calcium + Vitamin D + Bisphosphonate/Denosumab </b>— <i>except stop Bisphosphonate if atypical bisphosphonate fracture!</i>).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u336\">← Case 13</button><button class=\"nv\" data-u=\"u338\">Case 15 →</button></nav></article><article class=\"view unit\" id=\"u338\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 15</span><h1>Femoral Shaft Fracture &amp; FAT Embolism Syndrome (FES) Risk</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Femoral+Shaft+Fracture+%26+FAT+Embolism+Syndrome+%28FES%29+Risk\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Diaphyseal fracture of the femur between 5 cm below the lesser trochanter and the distal supracondylar flare. <b>Requires massive high-energy force in adults</b> (always suspect polytrauma!).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>High-Energy Trauma (Adults):</b> <b>MVC</b>, motorcycle crashes, pedestrian struck, falls from height, gunshot wounds.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Low-Energy / Pathologic (Suspect If Minimal Trauma!):</b> <b>Bone Metastases</b> (lytic lesion!), Osteoporosis, <b>Child Abuse</b> (if child <b>&lt; 12–18 months</b> before walking age!).</span></p><h3><b>3. Pathophysiology &amp; Muscle Deforming Forces</b></h3><p>Powerful thigh muscles pull fragments into characteristic deformity (proximal fragment <b>flexed by Iliopsoas</b> &amp; <b>abducted by Gluteus medius</b>; distal fragment <b>adducted by Adductors</b> &amp; <b>extended by Gastrocnemius</b>). Tears perforating vessels -&gt; <b>1,000 – 1,500 mL hidden blood loss</b> into thigh compartments!</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Agonizing thigh pain, gross swelling/tense thigh, shortening and angulation, inability to move leg.</li>\n<li class=\"l1\"><b>MANDATORY EXAM:</b> Check <b>Dorsalis Pedis / Posterior Tibial pulses</b> (rule out Superficial Femoral Artery injury!), <b>Sciatic Nerve</b>, <b>Ipsilateral Hip &amp; Knee</b> (10% have missed <b>ipsilateral femoral neck fracture</b>!).</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>AP &amp; Lateral X-Rays of ENTIRE Femur + Dedicated AP Pelvis/Hip + Knee X-Rays!</b></li>\n<li class=\"l1\"><b>Labs:</b> Serial <b>Hb/Hct</b> (Hematocrit), <mark class=\"hl rx\"><b>Type &amp; Cross-match</b></mark> , <b>CK</b> (Creatine Kinase — rhabdomyolysis), <mark class=\"hl mech\"><b>ABG</b></mark> (Arterial Blood Gas) if hypoxic!</li>\n</ul><h3><b>6. Complications (LIFE-THREATENING SYSTEMIC COMPLICATION = FAT EMBOLISM SYNDROME [FES]!)</b></h3><ul>\n<li class=\"l1\"><b>Hemorrhagic Shock</b>, <b>Fat Embolism Syndrome (FES)</b> (peaks <b>24–72 hrs</b> post-fracture — <mark class=\"hl lab\"><b>Classic Triad: Hypoxemia/ARDS + Neurological Confusion/Coma + Petechial Rash on chest/axilla/conjunctiva!</b></mark> ), <mark class=\"hl lab\"><b>ARDS</b></mark> , <mark class=\"hl lab\"><b>DVT/PE</b></mark> , Thigh Compartment Syndrome, Nonunion/Malunion.</li>\n</ul><h3><b>7. Treatment (Early Stabilization Prevents FES &amp; ARDS!)</b></h3><ul>\n<li class=\"l1\"><b>Initial ER Stabilization:</b> <b>Hare / Sager Traction Splint</b> (restores length, reduces bleeding and pain — <i>avoid if ipsilateral pelvic/tibia fracture!</i>).</li>\n<li class=\"l1\"><b>Definitive Treatment in Adults:</b> <b>Reamed, Locked Antegrade Intramedullary (IM) Nail within 24 Hours!</b> <i>(Use </i><i><b>Damage Control External Fixation</b></i><i> first ONLY if unstable polytrauma patient with head/chest injury or lethal triad!)</i>.</li>\n<li class=\"l1\"><b>Pediatric Femoral Shaft Treatment (By Age!):</b> &lt; 6 mos: <b>Pavlik Harness</b> | 6 mos – 5 yrs: <b>Immediate Spica Cast</b> | 6 – 11 yrs: <mark class=\"hl lab\"><b>Flexible Titanium Elastic Nails (TENS)</b></mark> | ≥ 11–12 yrs: <b>Rigid Trochanteric-Entry IM Nail</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u337\">← Case 14</button><button class=\"nv\" data-u=\"u339\">Case 16 →</button></nav></article><article class=\"view unit\" id=\"u339\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 16</span><h1>Knee Ligament &amp; Meniscal Injuries (ACL, PCL, MCL, LCL)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Knee+Ligament+%26+Meniscal+Injuries+%28ACL%2C+PCL%2C+MCL%2C+LCL%29\">🔍 Search on Google</a></header><h3><b>1. Definitions &amp; Mechanism of Injury (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>ACL</b> (Anterior Cruciate Ligament — <b>#1 Major Ligament Ruptured in Sports!</b>): Prevents anterior tibial translation. Mechanism: <b>Non-contact sudden deceleration, pivoting, or landing from a jump</b> (football/basketball/skiing!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>PCL</b> (Posterior Cruciate Ligament): Prevents posterior tibial translation. Mechanism: <b>Dashboard injury</b> (posterior blow to proximal tibia with flexed knee) or falling onto flexed knee!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>MCL</b> (Medial Collateral Ligament): Resists <b>valgus</b> stress (blow to <i>outer/lateral</i> side of knee).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>LCL</b> (Lateral Collateral Ligament): Resists <b>varus</b> stress (blow to <i>inner/medial</i> side of knee — check <b>Common Peroneal Nerve</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Meniscus (Medial &gt; Lateral):</b> Shock-absorbing fibrocartilage C-rings torn by <b>twisting on a planted flexed knee</b> (<b>O’Donoghue’s \"Unhappy Triad\"</b> = Valgus + External rotation blow tearing <b>ACL + MCL + Medial Meniscus</b>!).</span></p><h3><b>2. Clinical Picture &amp; Special Knee Exam Tests</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Structure</b></p></th><th><p><b>Classic History</b></p></th><th><p><b>Gold Standard Physical Exam Test</b></p></th></tr><tr><td><p><b>ACL</b></p></td><td><p>Audible <b>\"POP\"</b> + <b>Immediate Large Hemarthrosis (swells within 1–2 hours!)</b> + \"knee gives way\"</p></td><td><p><b>Lachman Test</b> (knee flexed 20–30° — <b>MOST SENSITIVE!</b>), Anterior Drawer (90°), <b>Pivot Shift Test</b> (most specific!)</p></td></tr><tr><td><p><b>PCL</b></p></td><td><p>Posterior knee blow; mild effusion</p></td><td><p><b>Posterior Sag Sign</b> (tibia sags backward at 90°) + <b>Posterior Drawer Test</b></p></td></tr><tr><td><p><b>MCL / LCL</b></p></td><td><p>Lateral blow (MCL) / Medial blow (LCL)</p></td><td><p><b>Valgus Stress Test</b> (at 0° &amp; 30° -&gt; <b>MCL</b>) | <b>Varus Stress Test</b> (at 0° &amp; 30° -&gt; <b>LCL</b>)</p></td></tr><tr><td><p><b>Meniscus</b></p></td><td><p>Delayed swelling (<b>12–24 hrs</b>); <b>clicking, catching, or TRUE \"LOCKED KNEE\"</b> (unable to fully extend in <b>Bucket-Handle Tear</b>!)</p></td><td><p><b>Joint Line Tenderness</b> (most sensitive!) + <b>McMurray’s Test</b> (painful click on rotation + extension) + <b>Thessaly Test</b></p></td></tr></table><h3><b>3. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Knee X-Rays (AP, Lateral, Sunrise):</b> Rule out fractures; look for <b>Segond Fracture</b> (small lateral tibial avulsion = <b>pathognomonic for ACL tear!</b>) or <b>Lipohaemarthrosis</b> (fat-fluid level = intra-articular fracture!).</li>\n<li class=\"l1\"><b>Diagnostic Gold Standard:</b> <mark class=\"hl mech\"><b>MRI Knee</b></mark> (visualizes ACL, PCL, menisci, cartilage, bone bruises).</li>\n</ul><h3><b>4. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Patellar dislocation (apprehension test +), Tibial plateau fracture, Osteochondral defect, Septic arthritis (if febrile!), Baker’s cyst rupture.</li>\n</ul><h3><b>5. Complications</b></h3><ul>\n<li class=\"l1\">Chronic knee instability, recurrent meniscal tears, early <mark class=\"hl lab\"><b>Post-Traumatic Knee Osteoarthritis</b></mark> , stiffness (arthrofibrosis).</li>\n</ul><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Initial Acute Care (All Injuries):</b> <b>RICE</b> (Rest, Ice, Compression, Elevation), NSAIDs, Crutches, early gentle ROM.</li>\n<li class=\"l1\"><b>ACL Tear:</b> <i>Low-demand/sedentary:</i> Physical therapy (quadriceps/hamstring strengthening). <i>Young/Active/Pivoting Athletes:</i> <b>Arthroscopic ACL Reconstruction </b>(Bone-Patellar Tendon-Bone or Hamstring autograft — wait until swelling resolves &amp; full ROM restored pre-op!).</li>\n<li class=\"l1\"><b>MCL Tear (Isolated):</b> <b>NON-OPERATIVE!</b> Rich blood supply -&gt; heals with <b>Hinged Knee Brace + Early ROM</b>!</li>\n<li class=\"l1\"><b>Meniscal Tear:</b> <i>Small peripheral tear:</i> Rest/PT. <i>Bucket-handle </i><i><b>\"Locked Knee\"</b></i><i> or refractory mechanical symptoms:</i> <b>Arthroscopic Meniscal Repair</b> (if peripheral \"red-red\" vascular zone!) or <b>Partial Meniscectomy</b> (preserve as much meniscus as possible!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u338\">← Case 15</button><button class=\"nv\" data-u=\"u340\">Case 17 →</button></nav></article><article class=\"view unit\" id=\"u340\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 17</span><h1>Tibial Plateau &amp; Tibial Shaft Fractures</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Tibial+Plateau+%26+Tibial+Shaft+Fractures\">🔍 Search on Google</a></header><h3><b>A. Tibial Plateau Fracture</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> High-energy valgus + axial load (classic <b>\"Pedestrian Bumper Injury\"</b> -&gt; <b>Lateral Plateau [Schatzker I–III] #1</b>!) or elderly osteoporotic fall!</li>\n<li class=\"l1\"><b>Clinical &amp; X-Ray Clues:</b> Severe knee swelling (<b>Hemarthrosis</b>), inability to bear weight; look for <b>Lipohaemarthrosis</b> (horizontal fat-fluid level on cross-table lateral X-ray!); <b>CT Knee</b> maps articular depression (<b>Schatzker Types I–VI</b>)!</li>\n<li class=\"l1\"><b>CRITICAL CHECKS:</b> <b>Acute Compartment Syndrome</b> + <b>Common Peroneal Nerve</b> (Schatzker IV–VI medial/bicondylar high-energy fractures risk <b>Popliteal Artery Injury</b>!).</li>\n<li class=\"l1\"><b>Treatment:</b> Non-displaced -&gt; Hinged brace, <b>non-weight-bearing 8–12 wks</b>; Joint depression <b>&gt; 2–3 mm</b> or instability -&gt; <b>ORIF with Buttress Plating</b> (spanning external fixator first if severe swelling/blisters!).</li>\n</ul><h3><b>B. Tibial Shaft Fracture (#1 Most Common Open Long-Bone Fracture!)</b></h3><ul>\n<li class=\"l1\"><b>Why So Often Open &amp; Slow to Heal?</b> The anteromedial tibia lies <b>directly subcutaneous</b> with minimal muscle cover, and its distal third has poor blood supply -&gt; <b>HIGH RISK OF OPEN FRACTURE, COMPARTMENT SYNDROME, &amp; NONUNION!</b></li>\n<li class=\"l1\"><b>Clinical &amp; Exam:</b> Deformity, pain; <b>MUST rule out Compartment Syndrome</b> (pain out of proportion + pain on <b>passive toe stretch</b> — do NOT wait for pulselessness!) and check <b>ipsilateral ankle/knee</b>.</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Closed Stable/Minimally Displaced (&lt; 5° varus/valgus, &lt; 10° AP, &lt; 1 cm shortening):</i> Long-leg splint -&gt; <b>Patellar-Tendon-Bearing (Sarmiento) Functional Cast</b>.</li>\n<li class=\"l2\"><i>Unstable / Displaced / Open:</i> <b>Reamed Locked Intramedullary (IM) Nail</b> (or External Fixator for severe open Grade IIIB/C)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u339\">← Case 16</button><button class=\"nv\" data-u=\"u341\">Case 18 →</button></nav></article><article class=\"view unit\" id=\"u341\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 18</span><h1>Ankle Sprains (OTTAWA ANKLE RULES) &amp; Ankle Fractures</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ankle+Sprains+%28OTTAWA+ANKLE+RULES%29+%26+Ankle+Fractures\">🔍 Search on Google</a></header><h3><b>A. Lateral &amp; High Ankle Sprains</b></h3><ul>\n<li class=\"l1\"><b>Lateral Ankle Sprain (~85–90% of All Sprains!):</b> <b>Inversion injury</b> -&gt; tears ligaments in predictable sequence: <b>(1) ATFL</b> (Anterior Talofibular Ligament — <b>#1 Most Commonly Injured!</b>), <b>(2) CFL</b> (Calcaneofibular), (3) PTFL. <i>Test:</i> <b>Anterior Drawer Test</b> of ankle (ATFL).</li>\n<li class=\"l1\"><b>High Ankle (Syndesmotic) Sprain:</b> External rotation + dorsiflexion -&gt; tears distal tibiofibular syndesmosis (<b>Positive Squeeze Test</b> [squeezing mid-calf causes ankle pain!] &amp; <b>External Rotation Test</b>) -&gt; longer recovery!</li>\n</ul><h3><b>B. Ottawa Ankle Rules (When Do You Need an Ankle X-Ray?!)</b></h3><ul>\n<li class=\"l1\">Obtain <b>Ankle X-Rays</b> ONLY if pain in malleolar zone <b>PLUS ANY 1 of:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Bony tenderness along the <b>posterior edge or tip of the LATERAL malleolus</b> (distal 6 cm), OR</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\">Bony tenderness along the <b>posterior edge or tip of the MEDIAL malleolus</b> (distal 6 cm), OR</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Inability to bear weight for 4 steps</b> both immediately after injury AND in the ER!</span></p>\n<ul>\n<li class=\"l1\"><i>(</i><i><b>Ottawa Foot Rules:</b></i><i> Midfoot pain + tenderness at </i><i><b>Navicular</b></i><i> OR </i><i><b>Base of 5th Metatarsal</b></i><i> OR inability to bear weight 4 steps -&gt; </i><i><b>Foot X-Ray</b></i><i>!)</i></li>\n</ul><h3><b>C. Ankle Fractures (Danis-Weber Classification &amp; Maisonneuve Trap!)</b></h3><ul>\n<li class=\"l1\"><b>Weber A:</b> Fibular fracture <b>BELOW</b> syndesmosis (usually stable -&gt; walking boot!).</li>\n<li class=\"l1\"><b>Weber B:</b> Fibular fracture <b>AT</b> syndesmosis level (check medial clear space / deltoid ligament — unstable if talar shift -&gt; <b>ORIF</b>!).</li>\n<li class=\"l1\"><b>Weber C:</b> Fibular fracture <b>ABOVE</b> syndesmosis -&gt; <b>Syndesmosis is TORN (UNSTABLE!)</b> -&gt; <b>ORIF + Syndesmotic Screws/Tightrope</b>!</li>\n<li class=\"l1\"><b>MAISONNEUVE FRACTURE TRAP:</b> Patient presents with <b>medial ankle pain/deltoid tear &amp; widened medial ankle joint</b> -&gt; <mark class=\"hl mech\"><b>ALWAYS PALPATE AND X-RAY THE PROXIMAL FIBULA NEAR THE KNEE!</b></mark> (Force travels up interosseous membrane and exits via a <b>Proximal Fibula Fracture</b>!).</li>\n</ul><h3><b>D. Treatment of Uncomplicated Ankle Sprains</b></h3><ul>\n<li class=\"l1\"><b>Early Functional Rehabilitation (Faster Recovery Than Prolonged Casting!):</b> <b>RICE</b> + <b>Aircast/Stirrup Ankle Brace</b> + <b>Early Weight-Bearing as tolerated</b> + <b>Proprioceptive / Balance Physical Therapy</b> (prevents chronic ankle instability!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u340\">← Case 17</button><button class=\"nv\" data-u=\"u342\">Case 19 →</button></nav></article><article class=\"view unit\" id=\"u342\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 19</span><h1>Achilles Tendon Rupture &amp; Plantar Fasciitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Achilles+Tendon+Rupture+%26+Plantar+Fasciitis\">🔍 Search on Google</a></header><h3><b>A. Acute Achilles Tendon Rupture</b></h3><ul>\n<li class=\"l1\"><b>Classic Patient &amp; Triggers:</b> Middle-aged male (\"Weekend Warrior\", 30–50 yrs) playing basketball/tennis/football; <b>Risk Factors:</b> <mark class=\"hl rx\"><b>Fluoroquinolones (Ciprofloxacin/Levofloxacin!)</b></mark> and <b>Local Corticosteroid Injections</b> into/near Achilles!</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Sudden explosive <b>\"POP\" or feeling of being kicked/shot in the back of the ankle</b> while pushing off!</li>\n<li class=\"l1\"><b>Exam Signs (DO NOT MISS AS AN \"ANKLE SPRAIN\"!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Palpable gap/defect</b> 2–6 cm above calcaneal insertion.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\">Weak plantarflexion (unable to stand on tiptoes on affected leg!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>POSITIVE THOMPSON (CALF SQUEEZE) TEST:</b> Prone patient with feet hanging off bed -&gt; <b>squeezing calf FAILS to plantarflex the foot</b> (<b>100% Pathognomonic!</b>).</span></p>\n<ul>\n<li class=\"l1\"><b>Treatment:</b> Clinical diagnosis (Ultrasound/MRI only if equivocal); <b>Equinus Cast / Functional Walking Boot with Heel Wedges</b> (gradually lowered over 6–8 wks — <i>outcomes similar to surgery with early functional rehab!</i>) OR <b>Surgical End-to-End Tendon Repair</b> (preferred in young competitive athletes -&gt; slightly lower re-rupture rate, higher wound risk!).</li>\n</ul><h3><b>B. Plantar Fasciitis (#1 Cause of Plantar Heel Pain!)</b></h3><ul>\n<li class=\"l1\"><b>Pathophysiology:</b> Chronic repetitive <b>micro-tearing &amp; degeneration</b> (NOT primarily inflammation!) of the plantar fascia at the medial calcaneal tuberosity (<b>Risk factors:</b> Obesity, prolonged standing, flat feet [pes planus] or high arches, tight Achilles tendon!).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Sharp stabbing pain under the <b>medial heel</b>, classically <b>WORST WITH THE VERY FIRST STEPS OUT OF BED IN THE MORNING</b> (or after sitting), improving after walking a few minutes, then aching at end of day! <i>(Note: Heel spur seen on X-ray is an incidental result of traction, NOT the cause of pain!)</i></li>\n<li class=\"l1\"><b>Treatment (~90% Resolve Within 6–12 Months Conservatively!):</b> <b>Plantar fascia &amp; Calf Stretching Exercises</b> (especially <i>before</i> getting out of bed!), <b>Silicone Heel Cups / Arch Supports</b>, supportive cushioned shoes (never walk barefoot on hard tiles!), <b>Night Splints</b> (keep fascia stretched overnight!), short-term NSAIDs; avoid repeated steroid injections (risks fat pad atrophy &amp; plantar fascia rupture!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u341\">← Case 18</button><button class=\"nv\" data-u=\"u343\">Case 20 →</button></nav></article><article class=\"view unit\" id=\"u343\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 20</span><h1>Calcaneal Fracture &amp; Lisfranc Midfoot Injury</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Calcaneal+Fracture+%26+Lisfranc+Midfoot+Injury\">🔍 Search on Google</a></header><h3><b>A. Calcaneal Fracture (\"Lover’s / Don Juan Fracture\")</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> High-energy axial load — <b>fall from a height (ladder/balcony/roof) landing directly on the heels!</b></li>\n<li class=\"l1\"><b>Clinical &amp; X-Ray Clues:</b> Severe heel pain, wide swollen bruised heel, inability to bear weight; <b>Lateral Foot X-Ray shows DECREASED BÖHLER’S ANGLE (&lt; 20°; normal 20–40°!)</b> -&gt; <b>CT Foot</b> for intra-articular subtalar involvement!</li>\n<li class=\"l1\"><mark class=\"hl dx\"><b>TWO CRITICAL MANDATORY RULES:</b></mark></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>ALWAYS EXAMINE AND X-RAY THE LUMBAR/THORACIC SPINE!</b> (~10–15% have an occult <b>L1–L2 Compression/Burst Fracture</b> from axial force transmission — plus ~10% are bilateral calcaneal fractures!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>MONITOR CLOSELY FOR FOOT COMPARTMENT SYNDROME!</b> (Tense painful foot -&gt; urgent fasciotomy!).</span></p>\n<ul>\n<li class=\"l1\"><b>Treatment:</b> Elevate &amp; ice until skin wrinkles return (\"wrinkle sign\" takes 1–2 wks to avoid wound sloughing!) -&gt; <b>ORIF</b> for displaced intra-articular subtalar fractures (non-displaced: non-weight-bearing cast 8–10 wks).</li>\n</ul><h3><b>B. Lisfranc (Tarsometatarsal) Midfoot Injury (FREQUENTLY MISSED -&gt; CHRONIC DISABILITY!)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Axial load on plantarflexed foot (misstepping off a curb, football/soccer tackle, MVC).</li>\n<li class=\"l1\"><b>KEY CLINICAL RED FLAG:</b> <b>Plantar Midfoot Ecchymosis</b> (bruising on the <i>sole</i> of the arch!) + severe midfoot tenderness + <b>inability to bear weight on tiptoes</b>!</li>\n<li class=\"l1\"><b>X-Ray Clue (Get WEIGHT-BEARING AP/Oblique Foot X-Rays or CT!):</b> <b>&gt; 2 mm diastasis (widening)</b> between the <b>1st and 2nd Metatarsal Bases</b> or small <b>\"Fleck Sign\"</b> (avulsion of Lisfranc ligament from 2nd MT base!).</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Anatomic ORIF</b> (screws/plates) or primary arthrodesis if displaced (&gt; 2 mm) — missed Lisfranc leads to severe midfoot collapse &amp; arthritis!</li>\n</ul>\n<p class=\"muted\"><i>End of Part 13B — Orthopedics (Cases 11–20 Complete!</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u342\">← Case 19</button><button class=\"nv\" data-u=\"u344\">Overview →</button></nav></article><article class=\"view unit\" id=\"u344\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Overview</span><h1>Orthopedics — Infections, Spine, Shoulder, Tumors &amp;</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Orthopedics+%E2%80%94+Infections%2C+Spine%2C+Shoulder%2C+Tumors+%26+medical\">🔍 Search on Google</a></header><h4><b>PEDIATRIC ORTHOPEDICS (CASES 21–30)</b></h4><nav class=\"un\"><button class=\"nv\" data-u=\"u343\">← Case 20</button><button class=\"nv\" data-u=\"u345\">Case 21 →</button></nav></article><article class=\"view unit\" id=\"u345\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 21</span><h1>Acute Septic Arthritis (ADULT &amp; PEDIATRIC)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Septic+Arthritis+%28ADULT+%26+PEDIATRIC%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Acute bacterial invasion of a synovial joint space causing <b>rapid enzymatic destruction of articular cartilage within 24–48 hours</b> (<b>TRUE ORTHOPEDIC EMERGENCY!</b>). <b>Knee (#1 in adults)</b> and <b>Hip/Knee (in children)</b> are most commonly affected.</p><h3><b>2. Etiology (Separated by Patient Group!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Hematogenous Spread (#1 Route — Especially in Children, Elderly &amp; Prosthetic Joints):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Overall #1 Pathogen (All Ages &gt; 2 Yrs):</i> <i><b>Staphylococcus aureus</b></i> (including <b>MRSA</b> [Methicillin-Resistant <i>S. aureus</i>]).</li>\n<li class=\"l2\"><i>Sexually Active Young Adults (15–35 Yrs):</i> <i><b>Neisseria gonorrhoeae</b></i> (Disseminated Gonococcal Infection — triad of <b>migratory polyarthralgia + tenosynovitis + pustular skin lesions on extremities</b>, OR monoarticular purulent knee!).</li>\n<li class=\"l2\"><i>Neonates / Infants (&lt; 2 Yrs):</i> <mark class=\"hl lab\"><b>GBS</b></mark> (Group B <i>Streptococcus</i>), <i>S. aureus</i>, <i>Kingella kingae</i>, Gram-negative rods.</li>\n<li class=\"l2\"><i>Sickle Cell Disease:</i> <i><b>Salmonella</b></i> species &amp; <i>S. aureus</i>.</li>\n<li class=\"l2\"><i>IV Drug Users:</i> <i>S. aureus</i> &amp; <i><b>Pseudomonas aeruginosa</b></i> (Sternoclavicular / SI joints!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Direct Inoculation / Contiguous Spread:</b> Joint aspiration/injection, arthroscopy, open joint trauma, adjacent osteomyelitis (classic in <b>pediatric hip/shoulder</b> where metaphysis is <i>intra-articular</i>!).</span></p><h3><b>3. Pathophysiology</b></h3><p>Bacteria enter synovium -&gt; massive <mark class=\"hl mech\"><b>PMN</b></mark> (Polymorphonuclear leukocyte) influx releases lysosomal proteolytic enzymes and cytokines (<b>IL-1, TNF-α</b>) -&gt; rapid irreversible proteoglycan &amp; collagen cartilage degradation + increased intra-articular pressure causing epiphyseal <b>AVN</b> (Avascular Necrosis — especially in pediatric hip!).</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Acute, Hot, Erythematous, Swollen, Exquisitely Tender SINGLE Joint</b> (monoarthritis ~85–90%) + Fever + <b>Severe Pain on EVEN MINIMAL PASSIVE RANGE OF MOTION</b> (<b>\"Pseudoparalysis\"</b> in infants — child refuses to move limb and cries whenever diaper is changed!).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Pediatric Hip Septic Arthritis — Kocher Criteria (4 Predictors):</b></mark></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Fever <b>&gt; 38.5°C</b>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Non-weight-bearing</b> (refuses to walk).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl mech\"><b>ESR</b></mark> (Erythrocyte Sedimentation Rate) <b>&gt; 40 mm/hr</b>.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><mark class=\"hl mech\"><b>WBC</b></mark> (White Blood Cell count) <b>&gt; 12,000/mm³</b> <i>(Plus </i><mark class=\"hl mech\"><i><b>CRP &gt; 2.0 mg/dL</b></i></mark><i> — ≥ 3–4 criteria = &gt; 90% probability -&gt; urgent hip aspiration/washout!)</i>.</span></p><h3><b>5. Investigations (GOLD STANDARD = IMMEDIATE ARTHROCENTESIS BEFORE ANTIBIOTICS!)</b></h3><ul>\n<li class=\"l1\"><b>Synovial Fluid Analysis (Diagnostic Comparison):</b></li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>Septic Arthritis:</b></mark> Cloudy/purulent fluid, <mark class=\"hl mech\"><b>WBC &gt; 50,000 cells/mm³</b></mark> (often &gt; 100,000) with <mark class=\"hl mech\"><b>&gt; 90% Neutrophils (PMNs)</b></mark> , low glucose, positive Gram stain (~50%) &amp; Culture (~80–90%)! <i>(Always examine for crystals too — gout and septic arthritis can coexist!)</i></li>\n<li class=\"l2\"><i>Inflammatory (Gout/RA):</i> WBC 2,000–50,000 | <i>Non-inflammatory (OA):</i> WBC &lt; 2,000.</li>\n<li class=\"l1\"><b>Blood Cultures (×2)</b>, <mark class=\"hl mech\"><b>CBC</b></mark> , <mark class=\"hl mech\"><b>ESR/CRP</b></mark> , <b>X-Ray</b> (rule out fracture/osteomyelitis; hip shows widened medial joint space), <b>Hip Ultrasound</b> (detects effusion in children!).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Gout / Pseudogout</b></mark> (check crystals!), <b>Transient Synovitis of Hip</b> (children, afebrile/well-appearing), <b>Acute Rheumatic Fever</b> (migratory), <b>Hemarthrosis </b>(trauma/hemophilia), Cellulitis/Bursitis (passive joint ROM preserved!).</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\">Irreversible articular cartilage destruction -&gt; <mark class=\"hl lab\"><b>Secondary Osteoarthritis / Joint Ankylosis</b></mark> , <b>AVN of Femoral Head</b> (pediatric hip!), <b>Growth plate arrest</b>, Sepsis / Death.</li>\n</ul><h3><b>8. Treatment (\"Drain the Pus + IV Antibiotics!\")</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>EMERGENT SURGICAL JOINT DRAINAGE &amp; WASHOUT (Arthroscopic Lavage or Open Arthrotomy):</b> <b>MANDATORY</b> (especially for Hip/Shoulder!) — antibiotics alone fail! <i>(Daily serial needle aspiration only for accessible joints if surgery contraindicated).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Immediate Empirical IV Antibiotics (After Aspiration!):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Adult Gram+ suspected / Unknown:</i> <mark class=\"hl rx\"><b>IV Vancomycin</b></mark> (covers MRSA) <mark class=\"hl rx\"><b>PLUS IV Ceftriaxone</b></mark> (covers Gram-negatives &amp; <i>Gonococcus</i>!).</li>\n<li class=\"l2\"><i>Gonococcal Arthritis:</i> <mark class=\"hl rx\"><b>IV Ceftriaxone 1 g/day</b></mark> (+ oral Azithromycin/Doxycycline for <i>Chlamydia</i> co-infection!).</li>\n<li class=\"l2\">De-escalate based on cultures for <b>2–4 weeks</b> (IV -&gt; oral step-down once clinically improving and CRP normalizing).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u344\">← Overview</button><button class=\"nv\" data-u=\"u346\">Case 22 →</button></nav></article><article class=\"view unit\" id=\"u346\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 22</span><h1>Acute &amp; Chronic Osteomyelitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+%26+Chronic+Osteomyelitis\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Infection of bone and bone marrow caused by pyogenic bacteria (or mycobacteria/fungi).</p><h3><b>2. Etiology (Separated by Route &amp; Patient!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Acute Hematogenous Osteomyelitis (Most Common in Children &lt; 12 Yrs — Hits Well-Vascularized Metaphysis!):</b></span></p>\n<ul>\n<li class=\"l2\"><i><b>Staphylococcus aureus</b></i> (#1 overall!), <i>Streptococcus pyogenes</i>, <i>Kingella kingae</i> (&lt; 4 yrs), <i><b>Salmonella</b></i> (in <b>Sickle Cell Disease!</b>).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Contiguous / Post-Traumatic Osteomyelitis (Most Common in Adults!):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Open fractures</b>, Orthopedic hardware, <b>Diabetic Foot Ulcers</b> (polymicrobial: <i>S. aureus</i>, Gram-negatives, Anaerobes), <b>Puncture wound through rubber-soled sneaker</b> -&gt; <i><b>Pseudomonas aeruginosa</b></i>!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Vertebral Osteomyelitis (Adults — Hematogenous from UTI/IVDU/Endocarditis):</b></mark> <i>S. aureus</i>, <i>E. coli</i>, <i><b>Mycobacterium tuberculosis</b></i> (<b>Pott’s Disease</b> — <i>very important in Egypt!</i> Spares disc space early, affects thoracic spine -&gt; gibbus deformity &amp; paraplegia!), <i><b>Brucella</b></i> (endemic in Egypt!).</span></p><h3><b>3. Pathophysiology of Chronic Osteomyelitis</b></h3><p>Pus spreads through Haversian/Volkmann canals -&gt; elevates periosteum -&gt; cuts off cortical blood supply -&gt; leaves dead necrotic bone fragment (<b>\"Sequestrum\"</b>) surrounded by a reactive shell of new living periosteal bone (<b>\"Involucrum\"</b>) and draining sinus tracts (<b>\"Cloaca\"</b>)!</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Acute Pediatric Hematogenous:</b> High fever, malaise, severe <b>localized point tenderness over the metaphysis</b> (near knee/hip/ankle), refusal to bear weight / move limb, late local erythema/swelling!</li>\n<li class=\"l1\"><b>Chronic Osteomyelitis:</b> Chronic dull bone pain, recurrent draining <b>cutaneous sinus tract</b> (discharging pus or tiny bone spicules!).</li>\n</ul><h3><b>5. Investigations (X-Ray Trap: Normal for First 10–14 Days!)</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> Markedly elevated <mark class=\"hl mech\"><b>ESR &amp; CRP</b></mark> (best to monitor response!), Leukocytosis (often normal in chronic/vertebral!), <b>Blood Cultures</b>.</li>\n<li class=\"l1\"><b>Imaging:</b></li>\n<li class=\"l2\"><b>Plain X-Ray:</b> Normal for the <b>first 10–14 days</b> (only shows soft tissue swelling early!); after 2–3 wks shows periosteal elevation, osteopenia, lytic lesions, <b>Sequestrum &amp; Involucrum</b>!</li>\n<li class=\"l2\"><b>GOLD STANDARD IMAGING:</b> <mark class=\"hl mech\"><b>MRI with Contrast</b></mark> (~95% sensitive &amp; specific — detects bone marrow edema within <b>24–48 hours!</b>).</li>\n<li class=\"l1\"><b>Microbiological Gold Standard:</b> <b>Bone Biopsy / Deep Tissue Culture</b> BEFORE starting antibiotics (unless septic!).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\"><b>Ewing Sarcoma</b> (mimics osteomyelitis with fever, high ESR, lytic diaphyseal lesion &amp; \"onion-skinning\"!), Septic arthritis, Cellulitis, <b>Charcot Arthropathy</b> (diabetics), Bone infarction (Sickle cell crisis).</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\">Chronic osteomyelitis (relapsing sinus tracts), <b>Pathologic fracture</b>, <b>Growth arrest / Limb-length discrepancy</b> (in kids), Epidural abscess/paraplegia (vertebral!), Secondary <b>SCC</b> (Squamous Cell Carcinoma — <b>\"Marjolin’s Ulcer\"</b> in chronic sinus tracts!), Secondary <b>Amyloidosis</b>.</li>\n</ul><h3><b>8. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Acute Hematogenous (No Abscess/Sequestrum):</b> <b>Prolonged Targeted IV/High-Bioavailability Oral Antibiotics for 4–6 Weeks</b> (start empiric <mark class=\"hl rx\"><b>IV Vancomycin + Ceftriaxone/Cefazolin</b></mark> , then tailor!).</li>\n<li class=\"l1\"><b>Subperiosteal Abscess / Chronic Osteomyelitis / Implant Infection / Vertebral Instability:</b> <b>Antibiotics ALONE FAIL!</b> Requires <b>RADICAL SURGICAL DEBRIDEMENT (Sequestrectomy)</b> + removal of loose hardware + dead-space management (antibiotic beads/muscle flap) <b>PLUS 6 Weeks Targeted Antibiotics</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u345\">← Case 21</button><button class=\"nv\" data-u=\"u347\">Case 23 →</button></nav></article><article class=\"view unit\" id=\"u347\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 23</span><h1>Spinal Trauma &amp; Incomplete Spinal Cord Syndromes</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Spinal+Trauma+%26+Incomplete+Spinal+Cord+Syndromes\">🔍 Search on Google</a></header><h3><b>1. Initial Spinal Trauma Principles (ATLS Immobilization)</b></h3><ul>\n<li class=\"l1\">Maintain <b>Cervical Collar + Log-Roll Precautions</b> in every major trauma until <b>C-spine</b> (Cervical Spine) is cleared clinically (<b>NEXUS</b> or <b>Canadian C-Spine Rules</b>) or via <b>CT Cervical Spine</b>!</li>\n<li class=\"l1\"><b>Spinal Shock</b> (temporary loss of all reflexes/tone <b>below injury</b> for 24–48 hrs; ends when <b>Bulbocavernosus Reflex returns</b>!) <b>VS.</b> <b>Neurogenic Shock</b> (high injury <b>≥ T6</b> -&gt; loss of sympathetic outflow -&gt; <b>Hypotension + BRADYCARDIA + Warm Skin</b> -&gt; treat with <mark class=\"hl rx\"><b>IV Fluids + Norepinephrine/Phenylephrine + Atropine</b></mark> !).</li>\n</ul><h3><b>2. Incomplete Spinal Cord Syndromes (EXAM CLASSIC — MEMORIZE THE 3 PATTERNS!)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><mark class=\"hl lab\"><b>Syndrome</b></mark></p></th><th><p><b>Typical Mechanism</b></p></th><th><p><b>Clinical Neurological Deficit</b></p></th><th><p><b>Prognosis</b></p></th></tr><tr><td><p><b>Central Cord Syndrome</b> <i>(#1 Most Common Incomplete!)</i></p></td><td><p><b>Hyperextension injury</b> in an <b>elderly patient with pre-existing cervical spondylosis</b> (rear-end MVC or chin fall!)</p></td><td><p><b>MOTOR WEAKNESS IN ARMS/HANDS &gt;&gt;&gt; LEGS</b> (\"cape-like\" patchy pain/temp loss; bladder often affected)</p></td><td><p><b>Good recovery</b> (legs recover first, fine hand control last!)</p></td></tr><tr><td><p><b>Brown-Séquard Syndrome </b><i>(Hemisection of Cord)</i></p></td><td><p><b>Penetrating trauma</b> (knife/gunshot) or lateral mass fracture</p></td><td><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Ipsilateral</b> motor paralysis (Corticospinal) 2. <b>Ipsilateral</b> loss of vibration &amp; proprioception (Dorsal columns)</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Contralateral</b> loss of <b>pain &amp; temperature</b> starting 1–2 levels below</span></p>\n<p>lesion (Spinothalamic)!</p></td><td><p><b>Best prognosis</b> of all incomplete syndromes!</p></td></tr><tr><td><p><b>Anterior Cord Syndrome</b></p></td><td><p>Flexion compression (<b>Burst fracture</b>) or<b> Anterior</b></p></td><td><p><b>Bilateral paralysis</b> +<b> Bilateral loss of pain</b></p></td><td><p><b>WORST prognosis</b> ( 10 20%</p></td></tr><tr><td><p><b>Anterior Cord Syndrome</b></p></td><td><p>Flexion-compression (<b>Burst fracture</b>) or <b>Anterior Spinal Artery</b> occlusion (aortic cross-clamp/dissection!)</p></td><td><p><b>Bilateral paralysis</b> + <b>Bilateral loss of pain &amp; temperature</b> below lesion; <b>SPARES Vibration &amp; Proprioception</b> (Dorsal columns intact!)</p></td><td><p><b>WORST prognosis</b> (~10–20% recovery)!</p></td></tr></table><h3><b>3. Treatment of Acute Spinal Cord Injury</b></h3><ul>\n<li class=\"l1\">Immobilize spine, maintain <b>MAP</b> (Mean Arterial Pressure) <b>85–90 mmHg for 7 days</b> (prevents secondary cord ischemia!), <mark class=\"hl mech\"><b>Urgent MRI Spine</b></mark> , early <b>Surgical Decompression &amp; Stabilization</b> (within 24 hrs if progressive/unstable!). <i>(High-dose IV Methylprednisolone is NO longer routinely recommended due to GI bleed/infection risks!).</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u346\">← Case 22</button><button class=\"nv\" data-u=\"u348\">Case 24 →</button></nav></article><article class=\"view unit\" id=\"u348\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 24</span><h1>Cervical Radiculopathy/myelopathy &amp; Lumbar Spinal Stenosis / Spondylolisthesis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cervical+Radiculopathy%2Fmyelopathy+%26+Lumbar+Spinal+Stenosis+%2F+Spondylolisthesis\">🔍 Search on Google</a></header><h3><b>A. Cervical Radiculopathy vs. Cervical Spondylotic Myelopathy</b></h3><ul>\n<li class=\"l1\"><b>Cervical Radiculopathy (Nerve Root Compression — C6/C7 #1):</b> Unilateral shooting neck-to-arm pain, paresthesia, diminished reflex (<b>C5</b> = Deltoid/Biceps reflex; <b>C6</b> = Wrist extensors/Brachioradialis/Thumb; <b>C7</b> = Triceps/Middle finger); <b>Positive Spurling’s Test</b> (axial load + neck extension/rotation toward painful side reproduces arm pain!). <i>Treat:</i> Physical therapy, NSAIDs, cervical collar briefly -&gt; <b>ACDF</b> (Anterior Cervical Discectomy &amp; Fusion) if progressive weakness/refractory &gt; 6–12 wks!</li>\n<li class=\"l1\"><b>Cervical Myelopathy (Spinal Cord Compression — DO NOT DELAY SURGERY!):</b> Progressive <b>clumsy hands</b> (dropping keys/buttons), <b>unsteady broad-based gait</b>, <b>UMN signs in legs</b> (hyperreflexia, Babinski +, clonus, <b>Hoffmann’s sign</b> in hands!), bowel/bladder urgency -&gt; <mark class=\"hl mech\"><b>MRI Cervical Spine -&gt; Surgical Decompression</b></mark> to halt irreversible paralysis!</li>\n</ul><h3><b>B. Lumbar Spinal Stenosis (Neurogenic Claudication vs. Vascular Claudication!)</b></h3><ul>\n<li class=\"l1\"><b>Pathology:</b> Age-related facet hypertrophy, ligamentum flavum thickening, and disc bulging narrowing the lumbar spinal canal (<b>L4–L5 #1</b>).</li>\n<li class=\"l1\"><b>Classic Symptom — Neurogenic Claudication:</b> Bilateral buttock/thigh/calf pain, numbness, and weakness with <b>walking or standing upright</b> (extension narrows canal!), <mark class=\"hl rx\"><b>RELIEVED BY SITTING DOWN OR LEANING FORWARD OVER A SHOPPING CART (\"Shopping Cart Sign\")</b></mark> !</li>\n<li class=\"l2\"><i>Distinguish From </i><mark class=\"hl lab\"><i><b>Vascular Claudication (PAD)</b></i></mark><i> :</i> Vascular claudication worsens uphill, is <b>relieved merely by STANDING STILL</b> (no need to sit/flex forward!), and has <b>diminished pedal pulses</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> Flexion-based physical therapy (stationary cycling!), NSAIDs, epidural steroid injections -&gt; <b>Surgical Laminectomy Decompression</b> if refractory!</li>\n</ul><h3><b>C. Spondylolisthesis &amp; Spondylolysis</b></h3><ul>\n<li class=\"l1\"><b>Spondylolysis:</b> Stress fracture of the <b>Pars Interarticularis</b> (<b>\"Scotty Dog\" wearing a collar</b> on oblique lumbar X-ray — classic in <b>young gymnasts/weightlifters</b> with back pain worse on <b>lumbar extension</b>!).</li>\n<li class=\"l1\"><b>Spondylolisthesis:</b> Forward slippage of one vertebra over the one below (L5 over S1 or L4 over L5 -&gt; palpable <b>\"step-off\"</b> on lower back!). Treat conservatively (PT/brace); surgical fusion if severe slippage (&gt; 50%), progression, or neurologic deficit!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u347\">← Case 23</button><button class=\"nv\" data-u=\"u349\">Case 25 →</button></nav></article><article class=\"view unit\" id=\"u349\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 25</span><h1>Rotator Cuff Tear, Impingement &amp; Frozen Shoulder</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Rotator+Cuff+Tear%2C+Impingement+%26+Frozen+Shoulder\">🔍 Search on Google</a></header><h4><b>High-Yield Differential of Chronic/Subacute Shoulder Pain (&gt; 40 Years)</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Condition</b></p></th><th><p><b>Pathophysiology</b></p></th><th><p><b>Classic Clinical Clues &amp; Exam Tests</b></p></th><th><p><b>Treatment</b></p></th></tr><tr><td><p><b>Subacromial Impingement / Rotator Cuff Tendinopathy</b></p></td><td><p>Compression of <b>Supraspinatus</b> tendon under acromion/CA ligament</p></td><td><p>Painful lateral deltoid ache <b>worse overhead &amp; sleeping on affected side</b>; <b>\"Painful Arc\" (60°–120° abduction)</b>; <b>Positive Neer &amp; Hawkins-Kennedy Tests</b>; <b>NORMAL passive ROM &amp; intact strength!</b></p></td><td><p>Rest from overhead work, <b>Physical Therapy </b>(scapular/rotator cuff rehab), NSAIDs, <b>Subacromial Steroid Injection</b></p></td></tr><tr><td><p><b>Full-Thickness Rotator Cuff Tear</b></p></td><td><p>Degenerative (elderly) or acute trauma/shoulder dislocation (&gt; 40 yrs); <b>Supraspinatus (#1!)</b></p></td><td><p>Night pain + <b>TRUE WEAKNESS </b>(<b>Positive \"Empty Can\" / Jobe Test </b>[supraspinatus]; <b>External Rotation Lag Sign</b> [infraspinatus]; <b>Lift-Off / Belly-Press Test</b> [subscapularis]; <b>Drop-Arm Test</b>)! <b>Passive ROM is FULL!</b></p></td><td><p><mark class=\"hl mech\"><b>MRI Shoulder</b></mark> (or Ultrasound); PT in elderly low-demand chronic tears; <b>Arthroscopic Rotator Cuff Repair</b> in <b>acute traumatic tears or young active patients</b>!</p></td></tr><tr><td><p><b>Adhesive Capsulitis (\"Frozen Shoulder\")</b></p></td><td><p>Fibrotic contracture of glenohumeral joint capsule (strongly linked to <b>DIABETES MELLITUS</b> &amp; <mark class=\"hl lab\"><b>Hypothyroidism</b></mark> , post-immobilization!)</p></td><td><p>Insidious stiffness &amp; pain (\"freezing -&gt; frozen -&gt; thawing\" over 1–2 yrs); <mark class=\"hl lab\"><b>HALLMARK: LOSS OF BOTH ACTIVE AND PASSIVE ROM IN ALL PLANES (ESPECIALLY EXTERNAL ROTATION!)</b></mark></p></td><td><p><b>Aggressive Physical Therapy</b> + NSAIDs + <b>Intra-articular Corticosteroid Injection</b> + <mark class=\"hl mech\"><b>Check HbA1c/TSH</b></mark> ! (Manipulation/capsular release if refractory)</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u348\">← Case 24</button><button class=\"nv\" data-u=\"u350\">Case 26 →</button></nav></article><article class=\"view unit\" id=\"u350\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 26</span><h1>Osteoporosis &amp; Fragility Fractures</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Osteoporosis+%26+Fragility+Fractures\">🔍 Search on Google</a></header><h3><b>1. Definition (WHO DEXA T-Score)</b></h3><p>Systemic skeletal disorder of <b>decreased bone mass (microarchitectural deterioration)</b> causing increased bone fragility and low-trauma (\"fragility\") fractures (fall from standing height or less).</p>\n<ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>DEXA</b></mark> (Dual-Energy X-Ray Absorptiometry) <b>T-Score:</b></li>\n<li class=\"l2\"><b>Normal:</b> ≥ −1.0 | <b>Osteopenia:</b> −1.1 to −2.4 | <mark class=\"hl lab\"><b>Osteoporosis:</b></mark> <b>≤ −2.5</b> (OR <b>ANY fragility fracture of hip/spine regardless of T-score!</b>).</li>\n</ul><h3><b>2. Etiology (Separated — Primary vs. Secondary)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Primary Osteoporosis:</b></mark> <b>Postmenopausal (Estrogen deficiency)</b> and <b>Age-related/Senile (&gt; 70 yrs)</b>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Secondary Osteoporosis (ALWAYS SCREEN IN MEN &amp; PREMENOPAUSAL WOMEN!):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><i>Endocrine:</i> <b>Hyperparathyroidism</b>, <mark class=\"hl lab\"><b>Hyperthyroidism</b></mark> , <b>Cushing’s Syndrome</b>, Hypogonadism, T1DM/T2DM.</li>\n<li class=\"l2\"><i>Drugs:</i> <mark class=\"hl rx\"><b>Long-Term Corticosteroids (≥ 5–7.5 mg Prednisone ≥ 3 mos — #1 drug cause!)</b></mark> , <mark class=\"hl rx\"><b>PPIs</b></mark> , Anticonvulsants (<b>Phenytoin/Carbamazepine</b>), Heparin, <b>DMPA</b>, Aromatase inhibitors.</li>\n<li class=\"l2\"><i>GI / Marrow / Lifestyle:</i> <b>Celiac Disease / Malabsorption</b>, <mark class=\"hl lab\"><b>Multiple Myeloma</b></mark> , RA, Smoking, Alcohol, Immobility.</li>\n</ul><h3><b>3. Screening &amp; Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Screen with DEXA Scan:</b></mark> ALL <b>Women ≥ 65 years</b>, Men ≥ 70 years, and younger postmenopausal women/men with risk factors (fragility fracture, long-term steroids, low body weight, smoking, RA).</li>\n<li class=\"l1\"><b>Mandatory Labs Before Treatment:</b> <mark class=\"hl mech\"><b>CBC, Serum Calcium, Albumin, Phosphate, RFTs, ALP, 25-OH Vitamin D, TSH</b></mark> (+/- <b>PTH</b> if hypercalcemic, <b>SPEP</b> if anemia/lytic lesions, <b>Morning Testosterone</b> in men!).</li>\n</ul><h3><b>4. Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Lifestyle &amp; Baseline Supplements:</b> Weight-bearing/resistance exercise, smoking cessation, fall prevention; <b>Calcium 1,000–1,200 mg/day</b> (diet + supplement) + <b>Vitamin D3 800–1,000+ IU/day</b> (maintain 25-OH Vit D &gt; 30 ng/mL!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>First-Line Antiresorptive Drugs:</b> <b>Oral Bisphosphonates</b> (<b>Alendronate</b> 70 mg weekly or <b>Risedronate</b> 35 mg weekly) OR <b>IV Zoledronic Acid</b> annually!</span></p>\n<ul>\n<li class=\"l2\"><i>CRITICAL BISPHOSPHONATE INSTRUCTIONS:</i> Take first thing in morning with a <b>full glass of plain water on an empty stomach</b>, and <b>REMAIN UPRIGHT FOR 30– 60 MINUTES</b> (prevents severe <b>pill esophagitis</b>!); avoid if <b>eGFR &lt; 30–35</b>! Warn about rare <b>Osteonecrosis of the Jaw (ONJ)</b> &amp; <b>Atypical Femoral Fracture </b>(consider \"drug holiday\" after 5 yrs oral / 3 yrs IV if stable!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Alternatives &amp; Very High-Risk (Multiple Fractures / T-Score &lt; −3.0):</b> <b>Denosumab</b> (RANKL inhibitor SC q6m — safe in CKD, <i>never stop abruptly without transitioning to bisphosphonate -&gt; rebound vertebral fractures!</i>) OR <b>Anabolic Agents</b> (<b>Teriparatide / Abaloparatide</b> or <b>Romosozumab</b>).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u349\">← Case 25</button><button class=\"nv\" data-u=\"u351\">Case 27 →</button></nav></article><article class=\"view unit\" id=\"u351\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 27</span><h1>Bone Tumors (BENIGN VS. MALIGNANT &amp; METASTATIC)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Bone+Tumors+%28BENIGN+VS.+MALIGNANT+%26+METASTATIC%29\">🔍 Search on Google</a></header><h3><b>1. Golden Rule of Bone Tumors</b></h3><ul>\n<li class=\"l1\"><b>#1 Malignant Bone Lesion Overall in Adults (&gt; 40–50 Yrs):</b> <mark class=\"hl mech\"><b>BONE METASTASES</b></mark> (<b>Prostate [blastic], Breast [mixed], Lung, Kidney, Thyroid</b>) and <mark class=\"hl lab\"><b>Multiple Myeloma</b></mark> (purely lytic \"punched-out\" lesions!).</li>\n<li class=\"l1\"><b>#1 Benign Bone Tumor:</b> <b>Osteochondroma</b>. | <b>#1 Primary Malignant Bone Tumor in Kids/Teens:</b> <b>Osteosarcoma</b>.</li>\n</ul><h3><b>2. High-Yield Primary Bone Tumors Comparison</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Tumor &amp; Typical Age</b></p></th><th><p><b>Classic Location</b></p></th><th><p><b>Key Clinical &amp; X-Ray Features</b></p></th><th><p><b>Treatment</b></p></th></tr><tr><td><p><b>Osteochondroma</b> <i>(Benign — #1 Overall!)</i></p></td><td><p>Metaphysis of long bones (<b>around Knee</b>)</p></td><td><p>Painless hard bump growing <i>away </i>from joint; <b>pedunculated bony stalk WITH continuous cortex &amp; marrow + cartilage cap</b>!</p></td><td><p>Observe (excise if painful/neurovascular compression or growing after skeletal maturity -&gt; rule out Chondrosarcoma!)</p></td></tr><tr><td><p><b>Osteoid Osteoma</b> <i>(Benign)</i></p></td><td><p>Cortex of Femur / Tibia (<b>Teens/20s</b>)</p></td><td><p><mark class=\"hl lab\"><b>NIGHT-TIME BONE PAIN DRAMATICALLY RELIEVED BY ASPIRIN / NSAIDs!</b></mark> Small <b>radiolucent nidus (&lt; 2 cm) surrounded by thick reactive sclerosis</b></p></td><td><p>NSAIDs or <b>CT-Guided Radiofrequency Ablation (RFA)</b>!</p></td></tr><tr><td><p><b>Giant Cell Tumor (GCT)</b> <i>(Locally Aggressive Benign!)</i></p></td><td><p><b>EPIPHYSIS</b> of distal femur / proximal tibia (<b>20–40 yrs, closed growth plates!</b>)</p></td><td><p>Knee pain; eccentric lytic <b>\"SOAP-BUBBLE\"</b> lesion extending right up to subchondral joint surface!</p></td><td><p>Intralesional curettage + bone cement/graft (+ Denosumab if unresectable)</p></td></tr><tr><td><p><b>Osteosarcoma</b> <i>(#1 Primary Malignant — </i><i><b>10–20 Yrs</b></i><i>!)</i></p></td><td><p><b>METAPHYSIS</b> around <b>KNEE</b> (Distal Femur / Proximal Tibia)</p></td><td><p>Progressive bone pain + swelling (worse at night), <mark class=\"hl mech\"><b>elevated ALP</b></mark> ; <b>\"SUNBURST\" periosteal reaction + \"CODMAN’S TRIANGLE\"</b>! <i>(Linked to </i><i><b>Retinoblastoma [RB1]</b></i><i> &amp; </i><i><b>Paget’s Disease</b></i><i> in elderly!)</i></p></td><td><p><b>Neoadjuvant Chemotherapy + Limb-Salvage Wide Surgical Resection + Adjuvant Chemo</b> (<b>NEVER do open biopsy outside sarcoma center!</b>)</p></td></tr><tr><td><p><b>Ewing Sarcoma</b> <i>(#2 Primary Malignant — </i><i><b>5–15 Yrs</b></i><i>!)</i></p></td><td><p><b>DIAPHYSIS</b> of femur/tibia/pelvis/ribs</p></td><td><p>Pain + <mark class=\"hl mech\"><b>FEVER + HIGH ESR/WBC (MIMICS OSTEOMYELITIS!)</b></mark> ; <b>\"ONION-SKIN\" (lamellated) periosteal reaction</b>; <b>t(11;22)</b> <i>EWSR1 </i>translocation; <b>small round blue cells</b>!</p></td><td><p><b>Neoadjuvant Chemo + Surgery and/or Radiation</b> (very radiosensitive!)</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u350\">← Case 26</button><button class=\"nv\" data-u=\"u352\">Case 28 →</button></nav></article><article class=\"view unit\" id=\"u352\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 28</span><h1>Developmental Dysplasia of the HIP (DDH) &amp; Congenital Clubfoot</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Developmental+Dysplasia+of+the+HIP+%28DDH%29+%26+Congenital+Clubfoot\">🔍 Search on Google</a></header><h3><b>A. Developmental Dysplasia of the Hip (DDH)</b></h3><ul>\n<li class=\"l1\"><b>Risk Factors (Mnemonic: \"4 Fs\"):</b> <b>F</b>emale (~80%), <b>F</b>irst-born, <b>F</b>rank <b>Breech</b> Presentation (#1 strongest!), <b>F</b>amily history (+ Oligohydramnios, tight swaddling with hips extended!).</li>\n<li class=\"l1\"><b>Screening Exam (Every Newborn &amp; Well-Baby Visit!):</b></li>\n<li class=\"l2\"><b>Barlow Maneuver</b> (\"Push Back/Out\"): Gently adduct &amp; push posteriorly -&gt; dislocates an unstable hip!</li>\n<li class=\"l2\"><b>Ortolani Maneuver</b> (\"Relocate IN\"): Abduct &amp; lift greater trochanter anteriorly -&gt; palpable <b>\"CLUNK\"</b> as dislocated femoral head reduces into acetabulum!</li>\n<li class=\"l2\"><i>Late Signs (&gt; 3 months — Barlow/Ortolani become negative due to contracture!):</i> <b>Asymmetric Gluteal/Thigh Skin Folds</b>, <b>Limited Hip Abduction</b>, <b>Galeazzi Sign </b>(unequal knee heights when supine with hips/knees flexed!), or <b>Trendelenburg waddling gait</b>!</li>\n<li class=\"l1\"><b>Imaging:</b> <b>&lt; 4–6 Months:</b> <b>Hip Ultrasound</b> (femoral head is cartilaginous — X-rays are useless!). <b>&gt; 4–6 Months:</b> <b>AP Pelvis X-Ray</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>&lt; 6 Months:</b> <b>Pavlik Harness</b> (holds hips in flexion &amp; abduction — ~90–95% cure!). <b>6–18 Months:</b> Closed reduction + <b>Hip Spica Cast</b>. <b>&gt; 18 Months:</b> Open surgical reduction + pelvic/femoral osteotomy!</li>\n</ul><h3><b>B. Congenital Clubfoot (</b><b>Talipes Equinovarus</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>4 Deformities (Mnemonic: \"CAVE\"):</b> Midfoot <b>C</b>avus (high arch), Forefoot <b>A</b>dductus, Hindfoot <b>V</b>arus (inverted heel), Hindfoot <b>E</b>quinus (plantarflexed)!</li>\n<li class=\"l1\"><b>Gold Standard Treatment (Start in First 1–2 Weeks of Life!):</b> <b>Ponseti Method</b> — <b>Serial Weekly Gentle Manipulation &amp; Long-Leg Casting</b> (corrects Cavus -&gt; Adductus -&gt; Varus FIRST, then <b>Percutaneous Achilles Tenotomy</b> for Equinus!) followed by <b>Foot Abduction Brace (Denis Browne Bar)</b> until age 4–5 years to prevent relapse!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u351\">← Case 27</button><button class=\"nv\" data-u=\"u353\">Case 29 →</button></nav></article><article class=\"view unit\" id=\"u353\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 29</span><h1>Pediatric HIP Limp — Transient Synovitis vs. Perthes vs. SCFE</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+HIP+Limp+%E2%80%94+Transient+Synovitis+vs.+Perthes+vs.+SCFE\">🔍 Search on Google</a></header><p><i>(EVERY pediatric hip pathology can refer pain purely to the </i><i><b>MEDIAL THIGH OR KNEE</b></i><i> via the Obturator Nerve — </i><i><b>ALWAYS EXAMINE THE HIP IN EVERY LIMPING CHILD!</b></i><i>)</i></p><h4><b>High-Yield 3-Way Differential (By Age &amp; Body Type!)</b></h4><table class=\"t \"><tr><td><p><b>Feature</b></p></td><td><p><b>Transient Synovitis </b><i><b>(#1 Cause of Pediatric Limp!)</b></i></p></td><td><p><b>Legg-Calvé-Perthes Disease </b><i><b>(Idiopathic AVN of Femoral Head)</b></i></p></td><td><p><b>SCFE </b><i><b>(Slipped Capital Femoral Epiphysis — SURGICAL URGENCY!)</b></i></p></td></tr><tr><td><p><b>Age &amp; Classic Child</b></p></td><td><p><b>3 – 8 Years</b> (recent viral <b>URTI</b> 1–2 wks ago)</p></td><td><p><b>4 – 10 Years</b> (<b>Active thin boy</b>, small for age, secondhand smoke!)</p></td><td><p><b>11 – 15 Years</b> (<b>OBESE adolescent boy</b> during growth spurt — <i>also screen Hypothyroidism/Renal osteodystrophy if atypical!</i>)</p></td></tr><tr><td><p><b>Presentation</b></p></td><td><p>Acute limp/hip pain; <b>WELL-APPEARING, AFEBRILE</b> (or low-grade &lt; 38°C), <b>willing to bear weight!</b></p></td><td><p><b>Painless/mildly painful INSIDIOUS LIMP </b>over weeks–months; <b>limited hip ABDUCTION &amp; INTERNAL ROTATION</b>!</p></td><td><p>Groin/thigh/<b>KNEE PAIN</b> + limp; leg held <mark class=\"hl lab\"><b>EXTERNALLY ROTATED</b></mark> ; <b>obligatory external rotation on passive hip flexion!</b></p></td></tr><tr><td><p><b>Labs &amp; X-Ray</b></p></td><td><p><mark class=\"hl mech\"><b>Normal WBC, Normal ESR/CRP </b></mark>(rules out <mark class=\"hl lab\"><b>Septic Arthritis</b></mark> per Kocher criteria!)</p></td><td><p>Early X-ray normal -&gt; later <b>dense flattened/fragmented femoral epiphysis </b>(MRI/Bone scan best early)</p></td><td><p><b>\"Ice-Cream Slipping Off the Cone\"</b> (<b>Klein’s Line </b>on Frog-Leg Lateral X-ray fails to intersect lateral epiphysis!)</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><b>Supportive:</b> Rest + <mark class=\"hl rx\"><b>NSAIDs </b></mark>(resolves completely in 1–2 weeks!)</p></td><td><p>Rest/NSAIDs + PT/bracing to keep head <b>contained</b> in acetabulum (&lt; 6–8 yrs best prognosis; osteotomy if severe &gt; 8 yrs)</p></td><td><p><b>IMMEDIATE NON-WEIGHT-BEARING (Crutches/Wheelchair!)</b> -&gt; <b>URGENT IN-SITU SINGLE CANNULATED SCREW PINNING</b> (prevents AVN &amp; <b>Chondrolysis</b>!)</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u352\">← Case 28</button><button class=\"nv\" data-u=\"u354\">Case 30 →</button></nav></article><article class=\"view unit\" id=\"u354\" hidden style=\"--c:#6d4c41\"><button class=\"back\" data-p=\"13\">← Orthopedics</button><header class=\"uh\"><span class=\"ul\">Case 30</span><h1>FAT Embolism Syndrome (FES) &amp; Complex Regional Pain Syndrome (CRPS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=FAT+Embolism+Syndrome+%28FES%29+%26+Complex+Regional+Pain+Syndrome+%28CRPS%29\">🔍 Search on Google</a></header><h3><b>A. Fat Embolism Syndrome (FES)</b></h3><ul>\n<li class=\"l1\"><b>Definition &amp; Timing:</b> Life-threatening systemic syndrome occurring <b>24 – 72 HOURS after long-bone (Femur/Tibia) or Pelvic fractures</b> (or intramedullary reaming/arthroplasty).</li>\n<li class=\"l1\"><b>Classic Triad (Gurd’s Criteria — Usually ≥ 1–2 Major + 4 Minor):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Respiratory Distress / Hypoxemia</b> (<b>#1 Earliest Sign!</b> Tachypnea, dyspnea, bilateral diffuse infiltrates / <mark class=\"hl lab\"><b>ARDS</b></mark> ).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Neurological Dysfunction</b> (Confusion, agitation, drowsiness, focal deficits, coma — <i>not explained by head injury!</i>).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Petechial Rash (~50–60% — PATHOGNOMONIC!):</b> Non-palpable pinpoint petechiae over <b>anterior chest/neck, axillae, oral mucosa, and conjunctivae</b>!</span></p>\n<ul>\n<li class=\"l1\"><b>Treatment &amp; Prevention:</b> <b>Supportive ICU Care ONLY</b> (Oxygen/Mechanical ventilation + IV fluids; <b>NO steroids or heparin routinely recommended!</b>) — <b>Best Prevention = Early (&lt; 24 hr) Operative Stabilization of Femoral/Tibial Fractures!</b></li>\n</ul><h3><b>B. Complex Regional Pain Syndrome (CRPS — Reflex Sympathetic Dystrophy)</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> Abnormal autonomic &amp; neuropathic pain dysregulation weeks after minor trauma, <b>Colles’ distal radius fracture</b>, ankle sprain, or tight cast/immobilization (<b>Type I:</b> no discrete nerve injury; <b>Type II [Causalgia]:</b> defined nerve injury).</li>\n<li class=\"l1\"><b>Clinical Picture (Budapest Criteria):</b> Severe burning/throbbing pain <b>OUT OF PROPORTION</b> to healed injury + <b>Allodynia</b> (light touch/breeze causes agonizing pain!) + <b>Autonomic/Trophic Changes</b> (asymmetric <b>sweating, skin temperature/color changes [warm red -&gt; cold cyanotic], shiny thin skin, stiff joints, patchy osteopenia on X-ray</b>)!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Early Physical &amp; Occupational Therapy (Desensitization &amp; Active Motion — CORNERSTONE!)</b> + <b>Neuropathic Pain Agents</b> (<b>Gabapentin, Pregabalin, Amitriptyline, Duloxetine</b>) + <mark class=\"hl mech\"><b>Vitamin C (500 mg/day × 50 days after wrist fractures reduces CRPS risk!)</b></mark> + Sympathetic nerve blocks if refractory!</li>\n</ul>\n<p class=\"muted\"><i>End of Part 13C — Orthopedics (30 Cases Complete!).</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u353\">← Case 29</button></nav></article>"});
